screenPanels.initJs:
function(container, apiUrl, tables) {
  let editingId = null;
  let processCounter = 0;
  let processes = [];

  // 生産指示書一覧の再描画
  function renderInstructions(rows) {
    const tbody = container.querySelector('#instruction-tbody');
    tbody.innerHTML = rows.map(row => {
      const statusColor = {
        '未着手': '#6b7280',
        '進行中': '#3b82f6', 
        '完了': '#10b981',
        '中止': '#ef4444'
      }[row.ステータス] || '#6b7280';

      const priorityText = {
        1: '高',
        2: '中', 
        3: '低'
      }[row.優先度] || row.優先度;

      return `
        <tr data-id="${row.生産指示書ID}" style="cursor: pointer;">
          <td>${row.生産指示書番号 || ''}</td>
          <td>${row.製品名 || ''}</td>
          <td>${row.製造ライン || ''}</td>
          <td style="text-align: right;">${row.生産予定数量 || 0}</td>
          <td style="text-align: right;">${row.生産実績数量 || 0}</td>
          <td>${priorityText}</td>
          <td><span style="color: ${statusColor}; font-weight: 500;">${row.ステータス || ''}</span></td>
          <td>${row.生産完了予定日時 ? new Date(row.生産完了予定日時).toLocaleDateString() : ''}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${row.生産指示書ID}" style="font-size: 0.8rem; padding: 0.3rem 0.6rem;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${row.生産指示書ID}" style="font-size: 0.8rem; padding: 0.3rem 0.6rem; margin-left: 0.3rem;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 工程明細の再描画
  function renderProcesses() {
    const processList = container.querySelector('#process-list');
    processList.innerHTML = processes.map((process, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 0.5rem; border: 1px solid var(--border); border-radius: 4px; margin-bottom: 0.5rem; background: var(--bg-main);">
        <div style="font-size: 0.85rem;">
          <span style="font-weight: 500;">${process.order}.</span>
          <span>${process.name}</span>
        </div>
        <button class="action-btn secondary remove-process-btn" data-index="${index}" style="font-size: 0.7rem; padding: 0.2rem 0.5rem;">削除</button>
      </div>
    `).join('');
  }

  // フォームクリア
  function clearForm() {
    editingId = null;
    processes = [];
    container.querySelector('#form-title').textContent = '新規生産指示書作成';
    container.querySelector('#input-number').value = '';
    container.querySelector('#input-product').value = '';
    container.querySelector('#input-line').value = '';
    container.querySelector('#input-quantity').value = '';
    container.querySelector('#input-priority').value = '';
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#input-notes').value = '';
    renderProcesses();
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) renderInstructions(rows);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const number = container.querySelector('#search-number').value;
    const status = container.querySelector('#search-status').value;
    const line = container.querySelector('#search-line').value;

    const rows = await window.aivicApi.list(4);
    if (!rows) return;

    const filtered = rows.filter(row => {
      return (!number || (row.生産指示書番号 && row.生産指示書番号.includes(number))) &&
             (!status || row.ステータス === status) &&
             (!line || row.製造ライン === line);
    });

    renderInstructions(filtered);
  });

  // 新規作成ボタン
  container.querySelector('#btn-create').addEventListener('click', () => {
    clearForm();
  });

  // 保存処理
  container.querySelector('#btn-save').addEventListener('click', async (e) => {
    e.preventDefault();

    const formData = {
      生産指示書番号: container.querySelector('#input-number').value || `INST-${Date.now()}`,
      製品名: container.querySelector('#input-product').value,
      製造ライン: container.querySelector('#input-line').value,
      生産予定数量: parseInt(container.querySelector('#input-quantity').value) || 0,
      優先度: parseInt(container.querySelector('#input-priority').value) || 3,
      生産開始予定日時: container.querySelector('#input-start-date').value,
      生産完了予定日時: container.querySelector('#input-end-date').value,
      ステータス: '未着手',
      備考: container.querySelector('#input-notes').value,
      生産実績数量: 0
    };

    if (!formData.製品名 || !formData.製造ライン || !formData.生産予定数量) {
      alert('必須項目を入力してください');
      return;
    }

    let result;
    if (editingId) {
      result = await window.aivicApi.update(4, editingId, formData);
    } else {
      result = await window.aivicApi.save(4, formData);
    }

    if (result) {
      clearForm();
      const rows = await window.aivicApi.list(4);
      if (rows) renderInstructions(rows);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    clearForm();
  });

  // 工程追加ボタン
  container.querySelector('#btn-add-process').addEventListener('click', () => {
    container.querySelector('#process-modal').style.display = 'block';
    container.querySelector('#modal-process').value = '';
    container.querySelector('#modal-order').value = processes.length + 1;
  });

  // 工程追加確定
  container.querySelector('#btn-add-process-confirm').addEventListener('click', () => {
    const processName = container.querySelector('#modal-process').value;
    const order = parseInt(container.querySelector('#modal-order').value);

    if (!processName || !order) {
      alert('工程と順序を入力してください');
      return;
    }

    processes.push({
      id: ++processCounter,
      name: processName,
      order: order
    });

    processes.sort((a, b) => a.order - b.order);
    renderProcesses();
    container.querySelector('#process-modal').style.display = 'none';
  });

  // 工程追加キャンセル
  container.querySelector('#btn-add-process-cancel').addEventListener('click', () => {
    container.querySelector('#process-modal').style.display = 'none';
  });

  // 画面遷移
  container.querySelector('#btn-distribute').addEventListener('click', () => {
    window.showScreen("scr-1780995244814");
  });

  container.querySelector('#btn-results').addEventListener('click', () => {
    window.showScreen("scr-1780995265664");
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この生産指示書を削除しますか？')) return;

      await window.aivicApi.delete(4, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(4);
      if (rows) renderInstructions(rows);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const rows = await window.aivicApi.list(4);
      if (!rows) return;

      const row = rows.find(r => r.生産指示書ID === editBtn.dataset.id);
      if (!row) return;

      editingId = row.生産指示書ID;
      container.querySelector('#form-title').textContent = '生産指示書編集';
      container.querySelector('#input-number').value = row.生産指示書番号 || '';
      container.querySelector('#input-product').value = row.製品名 || '';
      container.querySelector('#input-line').value = row.製造ライン || '';
      container.querySelector('#input-quantity').value = row.生産予定数量 || '';
      container.querySelector('#input-priority').value = row.優先度 || '';
      container.querySelector('#input-start-date').value = row.生産開始予定日時 || '';
      container.querySelector('#input-end-date').value = row.生産完了予定日時 || '';
      container.querySelector('#input-notes').value = row.備考 || '';
      return;
    }

    // 工程削除ボタン
    const removeProcessBtn = e.target.closest('.remove-process-btn');
    if (removeProcessBtn) {
      const index = parseInt(removeProcessBtn.dataset.index);
      processes.splice(index, 1);
      renderProcesses();
      return;
    }

    // 行クリック（編集）
    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      const editBtn = row.querySelector('.edit-btn');
      if (editBtn) editBtn.click();
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const PRODUCTION_ORDERS_TABLE = 3; // 生産指示書
  const MANUFACTURING_LINES_TABLE = 2; // 製造ライン
  const ALERTS_TABLE = 12; // アラート通知
  const ANOMALY_TABLE = 13; // 異常値検出ログ
  const PROGRESS_TABLE = 11; // 進捗管理

  // 生産指示書一覧の再描画
  function renderProductionOrders(rows) {
    const tbody = container.querySelector('#production-orders-tbody');
    tbody.innerHTML = rows.map(r => {
      const progressPercent = Math.round((r.生産実績数量 || 0) / (r.生産予定数量 || 1) * 100);
      const statusColor = r.ステータス === '完了' ? '#4ade80' : r.ステータス === '進行中' ? '#3b82f6' : '#94a3b8';

      return `
        <tr data-id="${r.生産指示書ID}">
          <td>${r.生産指示書番号 || ''}</td>
          <td>${r.製品名 || ''}</td>
          <td>${r.ライン名 || ''}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px;">
                <div style="height: 100%; width: ${progressPercent}%; background: var(--primary); border-radius: 3px;"></div>
              </div>
              <span style="font-size: 0.75rem; color: var(--text-muted);">${progressPercent}%</span>
            </div>
          </td>
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${statusColor}20; color: ${statusColor};">
              ${r.ステータス || ''}
            </span>
          </td>
          <td style="color: var(--text-muted); font-size: 0.875rem;">
            ${r.生産完了予定日時 ? new Date(r.生産完了予定日時).toLocaleDateString() : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  // 製造ライン稼働状況の描画
  function renderLineStatus(lines) {
    const container_elem = container.querySelector('#line-status-list');
    container_elem.innerHTML = lines.map(line => {
      const statusColor = {
        '稼働中': '#4ade80',
        '停止中': '#94a3b8', 
        'メンテナンス中': '#f59e0b',
        '故障中': '#ef4444'
      }[line.ライン状態] || '#94a3b8';

      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 0.75rem 0; border-bottom: 1px solid var(--border);">
          <div>
            <div style="font-weight: 500; color: var(--text);">${line.ライン名 || ''}</div>
            <div style="font-size: 0.75rem; color: var(--text-muted);">${line.製品名 || ''}</div>
          </div>
          <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${statusColor}20; color: ${statusColor};">
            ${line.ライン状態 || ''}
          </span>
        </div>
      `;
    }).join('');
  }

  // アラート通知の再描画
  function renderAlerts(rows) {
    const tbody = container.querySelector('#alerts-tbody');
    tbody.innerHTML = rows.map(r => {
      const priorityColor = {
        '緊急': '#ef4444',
        '高': '#f59e0b',
        '中': '#3b82f6',
        '低': '#94a3b8'
      }[r.重要度] || '#94a3b8';

      return `
        <tr data-id="${r.アラート通知ID}">
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${priorityColor}20; color: ${priorityColor};">
              ${r.重要度 || ''}
            </span>
          </td>
          <td>${r.アラート種別 || ''}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
            ${r.メッセージ内容 || ''}
          </td>
          <td style="color: var(--text-muted); font-size: 0.875rem;">
            ${r.作成日時 ? new Date(r.作成日時).toLocaleString() : ''}
          </td>
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${r.通知ステータス === '完了' ? '#4ade80' : '#f59e0b'}20; color: ${r.通知ステータス === '完了' ? '#4ade80' : '#f59e0b'};">
              ${r.通知ステータス || ''}
            </span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 異常値検出ログの再描画
  function renderAnomalyLog(rows) {
    const tbody = container.querySelector('#anomaly-tbody');
    tbody.innerHTML = rows.map(r => {
      const levelColor = {
        '重大': '#ef4444',
        '注意': '#f59e0b',
        '軽微': '#94a3b8'
      }[r.異常レベル] || '#94a3b8';

      return `
        <tr data-id="${r.異常値検出ログID}">
          <td>${r.検出項目名 || ''}</td>
          <td style="font-family: monospace;">${r.検出値 || ''}</td>
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${levelColor}20; color: ${levelColor};">
              ${r.異常レベル || ''}
            </span>
          </td>
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${r.対応状況 === '完了' ? '#4ade80' : '#f59e0b'}20; color: ${r.対応状況 === '完了' ? '#4ade80' : '#f59e0b'};">
              ${r.対応状況 || ''}
            </span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 工程別進捗チャートの描画
  function renderProgressChart(progressData) {
    const canvas = container.querySelector('#progress-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ（工程別進捗）
    const processes = ['材料準備', '加工', '組立', '検査', '梱包'];
    const progressValues = [95, 78, 65, 45, 20];

    const barHeight = 40;
    const barSpacing = 20;
    const startY = 30;
    const maxWidth = canvas.width - 200;

    processes.forEach((process, index) => {
      const y = startY + index * (barHeight + barSpacing);
      const progress = progressValues[index];
      const barWidth = (progress / 100) * maxWidth;

      // 背景バー
      ctx.fillStyle = '#374151';
      ctx.fillRect(120, y, maxWidth, barHeight);

      // 進捗バー
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(120, y, barWidth, barHeight);

      // 工程名
      ctx.fillStyle = '#d1d5db';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(process, 110, y + 25);

      // 進捗率
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'left';
      ctx.fillText(`${progress}%`, 130 + maxWidth, y + 25);
    });
  }

  // KPI更新
  function updateKPIs() {
    // 実際の計算ロジックはここに実装
    container.querySelector('#active-lines').textContent = '3/4';
    container.querySelector('#overall-progress').textContent = '78%';
    container.querySelector('#pending-alerts').textContent = '5';
    container.querySelector('#quality-rate').textContent = '96.2%';
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [productionOrders, lines, alerts, anomalies] = await Promise.all([
        window.aivicApi.list(PRODUCTION_ORDERS_TABLE),
        window.aivicApi.list(MANUFACTURING_LINES_TABLE),
        window.aivicApi.list(ALERTS_TABLE),
        window.aivicApi.list(ANOMALY_TABLE)
      ]);

      renderProductionOrders(productionOrders || []);
      renderLineStatus(lines || []);
      renderAlerts(alerts || []);
      renderAnomalyLog(anomalies || []);
      renderProgressChart();
      updateKPIs();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // フォールバック: 初期データを使用
      renderProductionOrders(tables[PRODUCTION_ORDERS_TABLE]?.records || []);
      renderLineStatus(tables[MANUFACTURING_LINES_TABLE]?.records || []);
      renderAlerts(tables[ALERTS_TABLE]?.records || []);
      renderAnomalyLog(tables[ANOMALY_TABLE]?.records || []);
      renderProgressChart();
      updateKPIs();
    }
  }

  // 更新ボタンイベント
  container.querySelector('#btn-refresh').addEventListener('click', loadInitialData);

  // フィルターイベント
  container.querySelector('#line-select').addEventListener('change', async () => {
    const selectedLine = container.querySelector('#line-select').value;
    const orders = await window.aivicApi.list(PRODUCTION_ORDERS_TABLE);
    const filtered = selectedLine ? 
      orders.filter(o => o.製造ラインID === selectedLine) : orders;
    renderProductionOrders(filtered);
  });

  container.querySelector('#alert-filter').addEventListener('change', async () => {
    const selectedPriority = container.querySelector('#alert-filter').value;
    const alerts = await window.aivicApi.list(ALERTS_TABLE);
    const filtered = selectedPriority ? 
      alerts.filter(a => a.重要度 === selectedPriority) : alerts;
    renderAlerts(filtered);
  });

  // 日付範囲フィルター
  const dateFromInput = container.querySelector('#date-from');
  const dateToInput = container.querySelector('#date-to');

  [dateFromInput, dateToInput].forEach(input => {
    input.addEventListener('change', async () => {
      const dateFrom = dateFromInput.value;
      const dateTo = dateToInput.value;

      if (dateFrom || dateTo) {
        const orders = await window.aivicApi.list(PRODUCTION_ORDERS_TABLE);
        const filtered = orders.filter(o => {
          const orderDate = new Date(o.生産開始予定日時).toISOString().split('T')[0];
          return (!dateFrom || orderDate >= dateFrom) && (!dateTo || orderDate <= dateTo);
        });
        renderProductionOrders(filtered);
      }
    });
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let selectedAnomalyId = null;

  // 異常値検出ログの再描画関数
  function renderAnomalies(anomalies) {
    const tbody = container.querySelector("#anomaly-tbody");
    tbody.innerHTML = anomalies.map(a => `
      <tr data-id="${a.異常値検出ログID}" style="cursor: pointer;" class="anomaly-row">
        <td>${new Date(a.検出日時).toLocaleString()}</td>
        <td>${a.製造ライン名 || '-'}</td>
        <td>${a.工程名 || '-'}</td>
        <td>${a.検出項目名}</td>
        <td>${a.検出値}</td>
        <td>${a.基準値下限}-${a.基準値上限}</td>
        <td><span style="color: ${a.異常レベル === '重大' ? '#dc3545' : a.異常レベル === '注意' ? '#ffc107' : '#28a745'}">${a.異常レベル}</span></td>
        <td><span style="color: ${a.対応状況 === '完了' ? '#28a745' : a.対応状況 === '対応中' ? '#ffc107' : '#dc3545'}">${a.対応状況}</span></td>
      </tr>
    `).join("");
  }

  // 異常値詳細表示
  function showAnomalyDetail(anomaly) {
    selectedAnomalyId = anomaly.異常値検出ログID;
    container.querySelector("#detail-product").textContent = anomaly.製品名 || '-';
    container.querySelector("#detail-order").textContent = anomaly.生産指示書番号 || '-';
    container.querySelector("#detail-method").textContent = anomaly.検出方法 || '-';
    container.querySelector("#detail-staff").textContent = anomaly.担当者名 || '-';
    container.querySelector("#cause-analysis").value = anomaly.原因分析結果 || '';
    container.querySelector("#improvement-action").value = anomaly.改善措置 || '';
  }

  // 品質検査結果グラフ描画
  function drawQualityChart() {
    const canvas = container.querySelector("#quality-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフデータ（サンプル）
    const data = [98.5, 97.8, 98.2, 96.5, 98.7, 99.1, 98.3];
    const labels = ['1/9', '1/10', '1/11', '1/12', '1/13', '1/14', '1/15'];

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸線描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ線描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((value, index) => {
      const x = padding + (chartWidth / (data.length - 1)) * index;
      const y = canvas.height - padding - ((value - 95) / 5) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#007bff';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';

    labels.forEach((label, index) => {
      const x = padding + (chartWidth / (data.length - 1)) * index;
      ctx.fillText(label, x, canvas.height - 10);
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(12).then(anomalies => {
    if (anomalies) {
      renderAnomalies(anomalies);
      if (anomalies.length > 0) {
        showAnomalyDetail(anomalies[0]);
      }
    }
  });

  // グラフ描画
  drawQualityChart();

  // 異常値検出実行ボタン
  container.querySelector("#btn-detect").addEventListener("click", async () => {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const lineId = container.querySelector("#line-select").value;

    if (!startDate || !endDate) {
      alert("検出期間を指定してください");
      return;
    }

    // 検出条件に基づいてフィルタリング
    const anomalies = await window.aivicApi.list(12);
    if (anomalies) {
      let filtered = anomalies.filter(a => {
        const detectionDate = new Date(a.検出日時);
        return detectionDate >= new Date(startDate) && detectionDate <= new Date(endDate);
      });

      if (lineId) {
        filtered = filtered.filter(a => a.製造ラインID === lineId);
      }

      renderAnomalies(filtered);
      if (filtered.length > 0) {
        showAnomalyDetail(filtered[0]);
      }
    }
  });

  // 履歴確認ボタン
  container.querySelector("#btn-history").addEventListener("click", () => {
    window.showScreen("scr-1780995189769");
  });

  // 分析結果更新ボタン
  container.querySelector("#btn-update-analysis").addEventListener("click", async () => {
    if (!selectedAnomalyId) {
      alert("異常値を選択してください");
      return;
    }

    const causeAnalysis = container.querySelector("#cause-analysis").value;
    const improvementAction = container.querySelector("#improvement-action").value;

    const updated = await window.aivicApi.update(12, selectedAnomalyId, {
      原因分析結果: causeAnalysis,
      改善措置: improvementAction,
      対応状況: causeAnalysis && improvementAction ? '対応中' : '未対応'
    });

    if (updated) {
      alert("分析結果を更新しました");
      // 一覧を再読み込み
      const anomalies = await window.aivicApi.list(12);
      if (anomalies) {
        renderAnomalies(anomalies);
      }
    }
  });

  // 異常値行クリックイベント
  container.addEventListener("click", async (e) => {
    const row = e.target.closest(".anomaly-row");
    if (row) {
      const anomalyId = row.dataset.id;
      const anomalies = await window.aivicApi.list(12);
      if (anomalies) {
        const anomaly = anomalies.find(a => a.異常値検出ログID === anomalyId);
        if (anomaly) {
          showAnomalyDetail(anomaly);

          // 選択行のハイライト
          container.querySelectorAll(".anomaly-row").forEach(r => r.style.background = "");
          row.style.background = "rgba(0,123,255,0.1)";
        }
      }
    }
  });

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector("#start-date").value = weekAgo;
  container.querySelector("#end-date").value = today;
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  let currentHistoryData = [];

  // 作業履歴テーブルの再描画
  function renderWorkHistory(histories) {
    currentHistoryData = histories;
    tbody.innerHTML = histories.map(h => {
      const startTime = h.作業開始日時 ? new Date(h.作業開始日時).toLocaleString('ja-JP') : '-';
      const statusBadge = getStatusBadge(h.作業ステータス);

      return `
        <tr data-id="${h.作業履歴ID}" style="cursor: pointer; border-bottom: 1px solid var(--border);">
          <td style="padding: 0.75rem; color: var(--text);">${startTime}</td>
          <td style="padding: 0.75rem; color: var(--text);">${h.生産指示書ID || '-'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${h.製品名 || '-'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${h.工程名 || '-'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${h.ライン名 || '-'}</td>
          <td style="padding: 0.75rem; color: var(--text);">${h.作業者名 || '-'}</td>
          <td style="padding: 0.75rem; text-align: right; color: var(--text);">${h.処理数量 || 0}</td>
          <td style="padding: 0.75rem; text-align: center;">${statusBadge}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${h.作業履歴ID}" style="padding: 0.25rem 0.5rem; background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 4px; font-size: 0.75rem;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function getStatusBadge(status) {
    const statusColors = {
      '開始': 'background: #3b82f6; color: #fff;',
      '完了': 'background: #10b981; color: #fff;',
      '中断': 'background: #f59e0b; color: #fff;',
      'エラー': 'background: #ef4444; color: #fff;'
    };
    const style = statusColors[status] || 'background: var(--bg-sidebar); color: var(--text);';
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; ${style}">${status || '不明'}</span>`;
  }

  // 初期データ読み込み
  window.aivicApi.list(11).then(histories => {
    if (histories) {
      renderWorkHistory(histories);
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const productName = container.querySelector("#product-name-search").value.trim();
    const lineFilter = container.querySelector("#line-filter").value;
    const dateFrom = container.querySelector("#date-from").value;
    const dateTo = container.querySelector("#date-to").value;
    const workerName = container.querySelector("#worker-search").value.trim();
    const instructionNumber = container.querySelector("#instruction-number").value.trim();

    const selectedProcesses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value);

    const histories = await window.aivicApi.list(11);
    if (!histories) return;

    const filtered = histories.filter(h => {
      if (productName && !(h.製品名 || '').includes(productName)) return false;
      if (lineFilter && h.ライン名 !== lineFilter) return false;
      if (workerName && !(h.作業者名 || '').includes(workerName)) return false;
      if (instructionNumber && !(h.生産指示書ID || '').includes(instructionNumber)) return false;

      if (dateFrom) {
        const workDate = new Date(h.作業開始日時);
        if (workDate < new Date(dateFrom)) return false;
      }
      if (dateTo) {
        const workDate = new Date(h.作業開始日時);
        if (workDate > new Date(dateTo + 'T23:59:59')) return false;
      }

      if (selectedProcesses.length > 0) {
        if (!selectedProcesses.includes(h.工程名)) return false;
      }

      return true;
    });

    renderWorkHistory(filtered);
  });

  // 検索条件クリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#product-name-search").value = '';
    container.querySelector("#line-filter").value = '';
    container.querySelector("#date-from").value = '';
    container.querySelector("#date-to").value = '';
    container.querySelector("#worker-search").value = '';
    container.querySelector("#instruction-number").value = '';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);

    window.aivicApi.list(11).then(histories => {
      if (histories) renderWorkHistory(histories);
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const histories = await window.aivicApi.list(11);
    if (!histories) return;

    const headers = ['作業開始日時', '生産指示書ID', '製品名', '工程名', 'ライン名', '作業者名', '処理数量', '良品数量', '不良品数量', '作業ステータス', '備考'];
    const csvContent = [
      headers.join(','),
      ...histories.map(h => [
        h.作業開始日時 || '',
        h.生産指示書ID || '',
        h.製品名 || '',
        h.工程名 || '',
        h.ライン名 || '',
        h.作業者名 || '',
        h.処理数量 || 0,
        h.良品数量 || 0,
        h.不良品数量 || 0,
        h.作業ステータス || '',
        (h.備考 || '').replace(/,/g, '，')
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", () => {
    window.aivicApi.list(11).then(histories => {
      if (histories) renderWorkHistory(histories);
    });
  });

  // 詳細表示
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const row = e.target.closest("tr[data-id]");

    if (detailBtn || (row && !e.target.closest("button"))) {
      const historyId = (detailBtn?.dataset.id) || row?.dataset.id;
      if (!historyId) return;

      const history = currentHistoryData.find(h => h.作業履歴ID === historyId);
      if (!history) return;

      // 基本情報表示
      const basicInfo = container.querySelector("#basic-info");
      basicInfo.innerHTML = `
        <div style="margin-bottom: 0.5rem;"><strong>作業履歴ID:</strong> ${history.作業履歴ID}</div>
        <div style="margin-bottom: 0.5rem;"><strong>生産指示書ID:</strong> ${history.生産指示書ID || '-'}</div>
        <div style="margin-bottom: 0.5rem;"><strong>工程:</strong> ${history.工程名 || '-'}</div>
        <div style="margin-bottom: 0.5rem;"><strong>製造ライン:</strong> ${history.ライン名 || '-'}</div>
        <div style="margin-bottom: 0.5rem;"><strong>作業者:</strong> ${history.作業者名 || '-'}</div>
        <div><strong>作業内容:</strong> ${history.作業内容 || '-'}</div>
      `;

      // 実績情報表示
      const resultInfo = container.querySelector("#result-info");
      const startTime = history.作業開始日時 ? new Date(history.作業開始日時).toLocaleString('ja-JP') : '-';
      const endTime = history.作業終了日時 ? new Date(history.作業終了日時).toLocaleString('ja-JP') : '-';

      resultInfo.innerHTML = `
        <div style="margin-bottom: 0.5rem;"><strong>開始日時:</strong> ${startTime}</div>
        <div style="margin-bottom: 0.5rem;"><strong>終了日時:</strong> ${endTime}</div>
        <div style="margin-bottom: 0.5rem;"><strong>処理数量:</strong> ${history.処理数量 || 0}</div>
        <div style="margin-bottom: 0.5rem;"><strong>良品数量:</strong> ${history.良品数量 || 0}</div>
        <div style="margin-bottom: 0.5rem;"><strong>不良品数量:</strong> ${history.不良品数量 || 0}</div>
        <div><strong>ステータス:</strong> ${getStatusBadge(history.作業ステータス)}</div>
      `;

      // 品質検査結果を取得・表示
      const qualityResults = container.querySelector("#quality-results");
      const qualityData = await window.aivicApi.list(7); // 品質検査結果テーブル

      if (qualityData) {
        const relatedQuality = qualityData.filter(q => q.生産指示書ID === history.生産指示書ID);

        if (relatedQuality.length > 0) {
          qualityResults.innerHTML = relatedQuality.map(q => `
            <div style="border-bottom: 1px solid var(--border); padding: 0.5rem 0; color: var(--text);">
              <div style="display: flex; justify-content: space-between; margin-bottom: 0.25rem;">
                <strong>${q.検査項目名}</strong>
                <span style="padding: 0.125rem 0.5rem; border-radius: 8px; font-size: 0.75rem; ${q.判定結果 === '合格' ? 'background: #10b981; color: #fff;' : 'background: #ef4444; color: #fff;'}">${q.判定結果}</span>
              </div>
              <div style="font-size: 0.875rem; color: var(--text-muted);">
                基準値: ${q.検査基準値 || '-'} | 実測値: ${q.実測値 || '-'}
              </div>
            </div>
          `).join('');
        } else {
          qualityResults.innerHTML = '<div style="color: var(--text-muted); font-size: 0.875rem;">品質検査結果がありません</div>';
        }
      } else {
        qualityResults.innerHTML = '<div style="color: var(--text-muted); font-size: 0.875rem;">品質検査結果を取得できませんでした</div>';
      }

      container.querySelector("#detail-modal").style.display = "block";
    }
  });

  // モーダル閉じる
  container.querySelector("#close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = "none";
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = "none";
  });

  // 編集ボタン（作業実績登録画面へ遷移）
  container.querySelector("#btn-edit-history").addEventListener("click", () => {
    window.showScreen("scr-1780995149463"); // 作業実績登録・工程引き継ぎ画面
  });

  // モーダル外クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  let currentProcess = null;
  let workStartTime = null;
  let isWorking = false;

  // 工程ボタンの選択状態管理
  function selectProcess(processId) {
    container.querySelectorAll('.process-btn').forEach(btn => {
      btn.style.background = 'transparent';
      btn.style.borderColor = 'rgba(255,255,255,0.18)';
    });

    const selectedBtn = container.querySelector(`[data-process="${processId}"]`);
    if (selectedBtn) {
      selectedBtn.style.background = 'var(--primary)';
      selectedBtn.style.borderColor = 'var(--primary)';
      selectedBtn.style.color = '#fff';
      currentProcess = processId;
    }
  }

  // 工程ボタンのイベント
  container.querySelectorAll('.process-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      selectProcess(btn.dataset.process);
    });
  });

  // 作業開始ボタン
  container.querySelector('#start-work-btn').addEventListener('click', async () => {
    const productionOrder = container.querySelector('#production-order-select').value;
    const workerId = container.querySelector('#worker-id').value;

    if (!productionOrder || !workerId || !currentProcess) {
      alert('生産指示書、作業者ID、工程を選択してください');
      return;
    }

    workStartTime = new Date();
    isWorking = true;

    // 作業履歴に開始記録を保存
    const workRecord = {
      生産指示書ID: productionOrder,
      工程ID: currentProcess,
      作業者ID: workerId,
      作業開始日時: workStartTime.toISOString(),
      作業ステータス: '開始',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: workerId
    };

    const saved = await window.aivicApi.save(11, workRecord); // 作業履歴テーブル
    if (saved) {
      container.querySelector('#start-work-btn').textContent = '作業中...';
      container.querySelector('#start-work-btn').style.background = 'var(--primary-hover)';
      alert('作業を開始しました');
    }
  });

  // 作業完了ボタン
  container.querySelector('#complete-work-btn').addEventListener('click', async () => {
    if (!isWorking) {
      alert('作業が開始されていません');
      return;
    }

    const completedQty = container.querySelector('#completed-qty').value;
    const defectQty = container.querySelector('#defect-qty').value || 0;

    if (!completedQty) {
      alert('完成数量を入力してください');
      return;
    }

    const workEndTime = new Date();
    const workerId = container.querySelector('#worker-id').value;
    const productionOrder = container.querySelector('#production-order-select').value;

    // 作業実績を保存
    const workResult = {
      生産指示書ID: productionOrder,
      工程ID: currentProcess,
      作業開始日時: workStartTime.toISOString(),
      作業終了日時: workEndTime.toISOString(),
      実績数量: parseInt(completedQty),
      良品数量: parseInt(completedQty) - parseInt(defectQty),
      不良品数量: parseInt(defectQty),
      作業者ID: workerId,
      作業状況: '完了',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: workerId
    };

    const saved = await window.aivicApi.save(6, workResult); // 作業実績テーブル
    if (saved) {
      isWorking = false;
      container.querySelector('#start-work-btn').textContent = '作業開始';
      container.querySelector('#start-work-btn').style.background = 'var(--primary)';
      alert('作業完了を記録しました');

      // 入力フィールドをクリア
      container.querySelector('#completed-qty').value = '';
      container.querySelector('#defect-qty').value = '';
    }
  });

  // 異常報告モーダル
  const alertModal = container.querySelector('#alert-modal');

  container.querySelector('#alert-btn').addEventListener('click', () => {
    alertModal.style.display = 'block';
  });

  container.querySelector('#cancel-alert-btn').addEventListener('click', () => {
    alertModal.style.display = 'none';
  });

  container.querySelector('#submit-alert-btn').addEventListener('click', async () => {
    const alertType = container.querySelector('#alert-type').value;
    const alertDetail = container.querySelector('#alert-detail').value;

    if (!alertType || !alertDetail) {
      alert('異常種別と詳細内容を入力してください');
      return;
    }

    const workerId = container.querySelector('#worker-id').value;
    const productionOrder = container.querySelector('#production-order-select').value;

    // アラート通知を保存
    const alertRecord = {
      アラート種別: alertType === 'equipment' ? '設備故障' : 
                   alertType === 'quality' ? '品質異常' :
                   alertType === 'material' ? '材料不良' : '安全問題',
      重要度: '高',
      タイトル: `${alertType === 'equipment' ? '設備故障' : 
                  alertType === 'quality' ? '品質異常' :
                  alertType === 'material' ? '材料不良' : '安全問題'}報告`,
      メッセージ内容: alertDetail,
      生産指示書ID: productionOrder,
      通知対象ユーザーID: workerId,
      通知ステータス: '未読',
      既読フラグ: false,
      対応完了フラグ: false,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: workerId
    };

    const saved = await window.aivicApi.save(13, alertRecord); // アラート通知テーブル
    if (saved) {
      alert('異常報告を送信しました');
      alertModal.style.display = 'none';
      container.querySelector('#alert-type').value = '';
      container.querySelector('#alert-detail').value = '';
    }
  });

  // 引き継ぎメモ保存
  container.querySelector('#save-memo-btn').addEventListener('click', async () => {
    const memo = container.querySelector('#handover-memo').value;
    const workerId = container.querySelector('#worker-id').value;
    const productionOrder = container.querySelector('#production-order-select').value;

    if (!memo || !workerId || !productionOrder) {
      alert('メモ内容、作業者ID、生産指示書を確認してください');
      return;
    }

    // 工程引き継ぎ情報を保存
    const handoverRecord = {
      生産指示書ID: productionOrder,
      引き継ぎ元工程ID: currentProcess,
      引き継ぎ先工程ID: 'next_process',
      ロット番号: `LOT-${Date.now()}`,
      引き継ぎ数量: parseInt(container.querySelector('#completed-qty').value || 0),
      作業状況: '完了',
      品質状況: '良好',
      注意事項: memo,
      引き継ぎ日時: new Date().toISOString(),
      引き継ぎ者ID: workerId,
      引き継ぎ状態: '引き継ぎ済み',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: workerId
    };

    const saved = await window.aivicApi.save(8, handoverRecord); // 工程引き継ぎ情報テーブル
    if (saved) {
      alert('引き継ぎメモを保存しました');
      container.querySelector('#handover-memo').value = '';
    }
  });

  // 生産指示書選択時の製品情報更新
  container.querySelector('#production-order-select').addEventListener('change', (e) => {
    const selectedOrder = e.target.value;

    // サンプル製品情報の更新
    if (selectedOrder === 'PO-2024-001') {
      container.querySelector('#product-name').textContent = 'エンジン部品A';
      container.querySelector('#product-code').textContent = 'ENG-A-001';
      container.querySelector('#planned-qty').textContent = '100個';
    } else if (selectedOrder === 'PO-2024-002') {
      container.querySelector('#product-name').textContent = 'フレーム組立B';
      container.querySelector('#product-code').textContent = 'FRM-B-002';
      container.querySelector('#planned-qty').textContent = '50個';
    } else if (selectedOrder === 'PO-2024-003') {
      container.querySelector('#product-name').textContent = '制御基板C';
      container.querySelector('#product-code').textContent = 'PCB-C-003';
      container.querySelector('#planned-qty').textContent = '200個';
    }
  });

  // 初期状態で最初の工程を選択
  selectProcess('cutting');
}

function(container, apiUrl, tables) {
  let currentProductionOrderId = null;
  let inspectionItems = [];

  // 現在日時を検査日時にセット
  const now = new Date();
