                 style="width: 100%; padding: 0.3rem; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text);"
                 value="${item.実測値 || ''}">
        </td>
        <td>${item.単位 || ''}</td>
        <td>
          <select class="judgment-result" data-index="${index}"
                  style="width: 100%; padding: 0.3rem; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text); accent-color: var(--primary);">
            <option value="">-</option>
            <option value="合格" ${item.判定結果 === '合格' ? 'selected' : ''}>合格</option>
