            <option value="要再検査" ${item.判定結果 === '要再検査' ? 'selected' : ''}>要再検査</option>
          </select>
        </td>
        <td>
          <input type="text" class="item-notes" data-index="${index}"
                 style="width: 100%; padding: 0.3rem; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text);"
                 value="${item.備考 || ''}">
        </td>
      </tr>
    `).join('');
  }

  // 製品情報表示
  function displayProductInfo(productionOrder) {
    if (!productionOrder) return;

    // 製品マスタから製品情報を取得
    const productMaster = tables[0].records.find(p => p.製品ID === productionOrder.製品ID);

    container.querySelector('#product-name').textContent = productMaster?.製品名 || '-';
    container.querySelector('#product-code').textContent = productMaster?.製品コード || '-';
    container.querySelector('#product-spec').textContent = productMaster?.規格 || '-';
    container.querySelector('#production-qty').textContent = `${productionOrder.生産予定数量 || 0} ${productMaster?.単位 || ''}`;
  }

  // 検査項目読み込み
  container.querySelector('#btn-load-inspection').addEventListener('click', async () => {
    const orderNo = container.querySelector('#production-order-no').value.trim();
    const processId = container.querySelector('#inspection-process').value;

    if (!orderNo) {
      alert('生産指示書番号を入力してください');
      return;
    }
    if (!processId) {
      alert('検査工程を選択してください');
      return;
    }

    // 生産指示書を検索
    const productionOrders = await window.aivicApi.list(4); // 生産指示書テーブル
    const order = productionOrders?.find(o => o.生産指示書番号 === orderNo);

    if (!order) {
      alert('指定された生産指示書が見つかりません');
      return;
    }

    currentProductionOrderId = order.生産指示書ID;
    displayProductInfo(order);

    // 品質基準から検査項目を取得
    const qualityStandards = await window.aivicApi.list(11); // 品質基準テーブル
    const standards = qualityStandards?.filter(s => 
      s.製品ID === order.製品ID && s.有効開始日 && new Date(s.有効開始日) <= new Date()
    ) || [];

    inspectionItems = standards.map(s => ({
      品質基準ID: s.品質基準ID,
      検査項目名: s.検査項目名,
      基準値: s.基準値,
      上限値: s.上限値,
      下限値: s.下限値,
      単位: s.単位,
      実測値: '',
      判定結果: '',
      備考: ''
    }));

    renderInspectionItems(inspectionItems);
  });

  // 自動判定
  container.querySelector('#btn-auto-judge').addEventListener('click', () => {
    const measuredInputs = container.querySelectorAll('.measured-value');
    const judgmentSelects = container.querySelectorAll('.judgment-result');

    measuredInputs.forEach((input, index) => {
      const measuredValue = parseFloat(input.value);
      const item = inspectionItems[index];

      if (!isNaN(measuredValue) && item) {
        const upperLimit = parseFloat(item.上限値);
        const lowerLimit = parseFloat(item.下限値);

        let judgment = '合格';
        if (!isNaN(upperLimit) && measuredValue > upperLimit) {
          judgment = '不合格';
        } else if (!isNaN(lowerLimit) && measuredValue < lowerLimit) {
          judgment = '不合格';
        }

        judgmentSelects[index].value = judgment;
        inspectionItems[index].判定結果 = judgment;
      }
    });

    // 総合判定を自動設定
    const hasFailure = Array.from(judgmentSelects).some(select => select.value === '不合格');
    const overallRadio = container.querySelector(`input[name="overall-result"][value="${hasFailure ? '不合格' : '合格'}"]`);
    if (overallRadio) overallRadio.checked = true;
  });

  // 実測値・判定結果の変更を監視
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('measured-value')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].実測値 = e.target.value;
    } else if (e.target.classList.contains('judgment-result')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].判定結果 = e.target.value;
    } else if (e.target.classList.contains('item-notes')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].備考 = e.target.value;
    }
  });

  // 下書き保存
  container.querySelector('#btn-save-draft').addEventListener('click', async () => {
    if (!currentProductionOrderId) {
      alert('生産指示書を読み込んでください');
      return;
    }

    // 検査結果データを一時保存（実装は省略）
    alert('下書きを保存しました');
  });

  // 検査結果登録
  container.querySelector('#btn-save-inspection').addEventListener('click', async () => {
    if (!currentProductionOrderId) {
      alert('生産指示書を読み込んでください');
      return;
    }

    const inspectorName = container.querySelector('#inspector-name').value.trim();
    const inspectionDateTime = container.querySelector('#inspection-datetime').value;
    const equipment = container.querySelector('#inspection-equipment').value;
    const overallResult = container.querySelector('input[name="overall-result"]:checked')?.value;
    const defectNotes = container.querySelector('#defect-notes').value.trim();

    if (!inspectorName) {
      alert('検査員名を入力してください');
      return;
    }
    if (!inspectionDateTime) {
      alert('検査日時を入力してください');
      return;
    }
    if (!overallResult) {
      alert('総合判定を選択してください');
      return;
    }

    // 各検査項目の結果を保存
    for (let i = 0; i < inspectionItems.length; i++) {
      const item = inspectionItems[i];
      const measuredValue = container.querySelector(`.measured-value[data-index="${i}"]`).value;
      const judgment = container.querySelector(`.judgment-result[data-index="${i}"]`).value;

      if (measuredValue || judgment) {
        const inspectionResult = {
          生産指示書ID: currentProductionOrderId,
          製品ID: null, // 生産指示書から取得する必要がある
          工程ID: container.querySelector('#inspection-process').value,
          検査項目名: item.検査項目名,
          検査基準値: item.基準値,
          実測値: measuredValue,
          判定結果: judgment || '未判定',
          検査数量: 1,
          不良数量: judgment === '不合格' ? 1 : 0,
          検査日時: inspectionDateTime,
          検査者ID: 'current-user-id', // 実際のユーザーIDを設定
          備考: item.備考 || defectNotes
        };

        const saved = await window.aivicApi.save(7, inspectionResult); // 品質検査結果テーブル
        if (!saved) {
          alert('検査結果の保存に失敗しました');
          return;
        }
      }
    }

    alert('検査結果を登録しました');

    // フォームをリセット
    container.querySelector('#production-order-no').value = '';
    container.querySelector('#inspection-process').value = '';
    container.querySelector('#inspector-name').value = '';
    container.querySelector('#defect-notes').value = '';
    container.querySelector('#product-name').textContent = '-';
    container.querySelector('#product-code').textContent = '-';
    container.querySelector('#product-spec').textContent = '-';
    container.querySelector('#production-qty').textContent = '-';

    const overallRadios = container.querySelectorAll('input[name="overall-result"]');
    overallRadios.forEach(radio => radio.checked = false);

    inspectionItems = [];
    renderInspectionItems([]);
    currentProductionOrderId = null;
  });

  // 初期表示
  renderInspectionItems([]);
}

function(container, apiUrl, tables) {
  // 生産指示書テーブルのインデックスを特定
  const productionOrderTableIndex = tables.findIndex(t => t.tableName === '生産指示書');
  const productTableIndex = tables.findIndex(t => t.tableName === '製品マスタ');
  const processTableIndex = tables.findIndex(t => t.tableName === '工程マスタ');
  const lineTableIndex = tables.findIndex(t => t.tableName === '製造ライン');

  // 製品仕様プレビュー更新
  function updateProductSpec(productId) {
    const previewEl = container.querySelector('#product-spec-preview');
    if (!productId) {
      previewEl.innerHTML = '<p style="color: var(--text-muted); font-size: 0.9rem; margin: 0;">製品を選択すると仕様が表示されます</p>';
      return;
    }

    // 製品情報を取得して表示
    const products = tables[productTableIndex]?.records || [];
    const product = products.find(p => p.製品ID === productId);

    if (product) {
      previewEl.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.8rem; font-size: 0.9rem;">
          <div><strong style="color: var(--text);">製品名:</strong> <span style="color: var(--text-muted);">${product.製品名 || ''}</span></div>
          <div><strong style="color: var(--text);">製品コード:</strong> <span style="color: var(--text-muted);">${product.製品コード || ''}</span></div>
          <div><strong style="color: var(--text);">規格:</strong> <span style="color: var(--text-muted);">${product.規格 || ''}</span></div>
          <div><strong style="color: var(--text);">単位:</strong> <span style="color: var(--text-muted);">${product.単位 || ''}</span></div>
          <div style="grid-column: 1 / -1;"><strong style="color: var(--text);">備考:</strong> <span style="color: var(--text-muted);">${product.備考 || 'なし'}</span></div>
        </div>
      `;
    }
  }

  // 工程テーブル再描画
  function renderProcesses(processes) {
    const tbody = container.querySelector('#process-tbody');
    tbody.innerHTML = processes.map(p => `
      <tr>
        <td style="padding: 0.6rem; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.1);">${p.工程名 || ''}</td>
        <td style="padding: 0.6rem; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.1);">${p.標準作業時間 || ''}分</td>
        <td style="padding: 0.6rem; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.1);">
          <button class="action-btn secondary delete-process-btn" data-id="${p.工程ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 0.3rem 0.6rem; border-radius: 3px; font-size: 0.8rem;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期工程データ表示
  if (processTableIndex >= 0) {
    renderProcesses(tables[processTableIndex].records || []);
  }

  // 製品選択時の仕様プレビュー更新
  container.querySelector('#product-select').addEventListener('change', (e) => {
    updateProductSpec(e.target.value);
  });

  // 生産指示書登録
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const formData = {
      生産指示書番号: container.querySelector('#order-number').value || `PO-${Date.now()}`,
      製品ID: container.querySelector('#product-select').value,
      製造ラインID: container.querySelector('#line-select').value,
      生産予定数量: parseInt(container.querySelector('#quantity').value) || 0,
      生産開始予定日時: container.querySelector('#start-datetime').value,
      生産完了予定日時: container.querySelector('#end-datetime').value,
      優先度: parseInt(container.querySelector('input[name="priority"]:checked')?.value) || 2,
      ステータス: '未着手',
      備考: container.querySelector('#remarks').value,
      作成者ID: 'current-user-id',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    if (!formData.製品ID || !formData.製造ラインID) {
      alert('製品と製造ラインを選択してください');
      return;
    }

    const saved = await window.aivicApi.save(productionOrderTableIndex, formData);
    if (saved) {
      alert('生産指示書を登録しました');
      // フォームリセット
      container.querySelector('#production-order-form').reset();
      updateProductSpec('');
    }
  });

  // 製品仕様参照画面への遷移
  container.querySelector('#btn-spec-ref').addEventListener('click', () => {
    window.showScreen("scr-1780995221537");
  });

  // 工程追加モーダル制御
  const modal = container.querySelector('#process-modal');

  container.querySelector('#btn-add-process').addEventListener('click', () => {
    modal.style.display = 'flex';
  });

  container.querySelector('#btn-modal-cancel').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  container.querySelector('#btn-modal-add').addEventListener('click', async () => {
    const processId = container.querySelector('#modal-process-select').value;
    if (!processId) {
      alert('工程を選択してください');
      return;
    }

    // 工程マスタから選択された工程を取得
    const processes = tables[processTableIndex]?.records || [];
    const selectedProcess = processes.find(p => p.工程ID === processId);

    if (selectedProcess) {
      // 工程テーブルに追加（実際のアプリでは生産指示書明細テーブルに保存）
      const currentProcesses = [...(tables[processTableIndex]?.records || [])];
      if (!currentProcesses.find(p => p.工程ID === processId)) {
        currentProcesses.push(selectedProcess);
        renderProcesses(currentProcesses);
      }
    }

    modal.style.display = 'none';
    container.querySelector('#modal-process-select').value = '';
  });

  // 工程削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-process-btn');
    if (deleteBtn) {
      if (confirm('この工程を削除しますか？')) {
        const processId = deleteBtn.dataset.id;
        const currentProcesses = (tables[processTableIndex]?.records || []).filter(p => p.工程ID !== processId);
        renderProcesses(currentProcesses);
      }
    }
  });

  // モーダル外クリックで閉じる
  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      modal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#distribution-datetime').value = now.toISOString().slice(0, 16);

  // 選択された指示書IDを管理
  let selectedInstructions = new Set();

  // 未配信指示書の再描画関数
  function renderInstructions(instructions) {
    const tbody = container.querySelector('#instruction-tbody');
    tbody.innerHTML = instructions.map(inst => `
      <tr data-id="${inst.生産指示書ID}" style="cursor: pointer;">
        <td>
          <input type="checkbox" class="instruction-checkbox" data-id="${inst.生産指示書ID}" style="accent-color: var(--primary);">
        </td>
        <td>${inst.生産指示書番号 || ''}</td>
        <td>${inst.製品名 || ''}</td>
        <td>${inst.生産予定数量 || 0}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${inst.優先度 === 1 ? '#ff4444' : inst.優先度 === 2 ? '#ff8800' : inst.優先度 === 3 ? '#0088ff' : '#888888'}; 
                       color: #fff;">
            ${inst.優先度 === 1 ? '緊急' : inst.優先度 === 2 ? '高' : inst.優先度 === 3 ? '中' : '低'}
          </span>
        </td>
        <td>${inst.生産開始予定日時 ? new Date(inst.生産開始予定日時).toLocaleString() : ''}</td>
      </tr>
    `).join('');
  }

  // 配信履歴の再描画関数
  function renderHistory(history) {
    const tbody = container.querySelector('#history-tbody');
    tbody.innerHTML = history.map(h => `
      <tr>
        <td>${h.配信日時 ? new Date(h.配信日時).toLocaleString() : ''}</td>
        <td>${h.生産指示書番号 || ''}</td>
        <td>${h.配信先 || ''}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${h.ステータス === '配信完了' ? '#00aa44' : h.ステータス === '配信中' ? '#0088ff' : '#ff4444'}; 
                       color: #fff;">
            ${h.ステータス || ''}
          </span>
        </td>
        <td style="color: ${h.エラー ? '#ff6666' : 'var(--text)'};">${h.エラー || '-'}</td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(instructions => {
    if (instructions) {
      // 未配信のもののみフィルタ
      const undelivered = instructions.filter(inst => inst.ステータス === '未着手' || inst.ステータス === '承認済み');
      renderInstructions(undelivered);
    }
  });

  // 検索機能
  container.querySelector('#search-instruction').addEventListener('input', async (e) => {
    const keyword = e.target.value.toLowerCase();
    const instructions = await window.aivicApi.list(4);
    if (instructions) {
      const undelivered = instructions.filter(inst => 
        (inst.ステータス === '未着手' || inst.ステータス === '承認済み') &&
        (inst.生産指示書番号?.toLowerCase().includes(keyword) || 
         inst.製品名?.toLowerCase().includes(keyword))
      );
      renderInstructions(undelivered);
    }
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.instruction-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedInstructions.add(cb.dataset.id);
      } else {
        selectedInstructions.delete(cb.dataset.id);
      }
    });
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('instruction-checkbox')) {
      const id = e.target.dataset.id;
      if (e.target.checked) {
        selectedInstructions.add(id);
      } else {
        selectedInstructions.delete(id);
      }
    }
  });

  // プレビュー機能
  container.querySelector('#btn-preview').addEventListener('click', async () => {
    const previewContent = container.querySelector('#preview-content');

    if (selectedInstructions.size === 0) {
      previewContent.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 2rem;">配信する指示書を選択してください</div>';
      return;
    }

    const line = container.querySelector('#manufacturing-line').value;
    const worker = container.querySelector('#target-worker').value;
    const datetime = container.querySelector('#distribution-datetime').value;
    const priority = container.querySelector('#priority').value;

    const instructions = await window.aivicApi.list(4);
    if (instructions) {
      const selectedData = instructions.filter(inst => selectedInstructions.has(inst.生産指示書ID));

      previewContent.innerHTML = `
        <div style="margin-bottom: 1rem; padding: 1rem; background: rgba(0,0,0,0.2); border-radius: 4px;">
          <h4 style="margin: 0 0 0.5rem 0; color: var(--text);">配信設定</h4>
          <div style="color: var(--text-muted); font-size: 0.9rem;">
            <div>製造ライン: ${line || '未選択'}</div>
            <div>配信先: ${worker || '未選択'}</div>
            <div>配信日時: ${datetime ? new Date(datetime).toLocaleString() : '未設定'}</div>
            <div>優先度: ${priority === '1' ? '緊急' : priority === '2' ? '高' : priority === '3' ? '中' : priority === '4' ? '低' : '未設定'}</div>
          </div>
        </div>
        <div>
          <h4 style="margin: 0 0 0.5rem 0; color: var(--text);">配信対象指示書 (${selectedData.length}件)</h4>
          ${selectedData.map(inst => `
            <div style="margin-bottom: 0.5rem; padding: 0.8rem; background: rgba(255,255,255,0.05); border-radius: 4px; border-left: 3px solid var(--primary);">
              <div style="font-weight: bold; color: var(--text);">${inst.生産指示書番号}</div>
              <div style="color: var(--text-muted); font-size: 0.9rem;">
                製品: ${inst.製品名} | 数量: ${inst.生産予定数量} | 開始予定: ${inst.生産開始予定日時 ? new Date(inst.生産開始予定日時).toLocaleString() : '未設定'}
              </div>
            </div>
          `).join('')}
        </div>
      `;
    }
  });

  // 配信実行
  container.querySelector('#btn-distribute').addEventListener('click', async () => {
    if (selectedInstructions.size === 0) {
      alert('配信する指示書を選択してください');
      return;
    }

    const line = container.querySelector('#manufacturing-line').value;
    const worker = container.querySelector('#target-worker').value;
    const datetime = container.querySelector('#distribution-datetime').value;

    if (!line || !worker || !datetime) {
      alert('配信設定を全て入力してください');
      return;
    }

    if (!confirm(`${selectedInstructions.size}件の指示書を配信しますか？`)) {
      return;
    }

    // 配信処理（実際の配信ログを作成）
    const instructions = await window.aivicApi.list(4);
    if (instructions) {
      const selectedData = instructions.filter(inst => selectedInstructions.has(inst.生産指示書ID));

      for (const inst of selectedData) {
        // 指示書のステータスを更新
        await window.aivicApi.update(4, inst.生産指示書ID, {
          ステータス: '配信済み',
          更新日時: new Date().toISOString()
        });

        // 配信履歴を作成（アラート通知テーブルを使用）
        await window.aivicApi.save(12, {
          アラート種別: '指示書配信',
          重要度: '中',
          タイトル: `指示書配信完了: ${inst.生産指示書番号}`,
          メッセージ内容: `製造ライン: ${line}, 配信先: ${worker}`,
          生産指示書ID: inst.生産指示書ID,
          製造ラインID: line,
          通知対象ユーザーID: worker,
          通知ステータス: '配信完了',
          既読フラグ: false,
          対応完了フラグ: true,
          作成日時: datetime,
          作成者ID: 'system'
        });
      }

      alert('配信が完了しました');
      selectedInstructions.clear();
      container.querySelector('#select-all').checked = false;

      // 一覧を更新
      const updatedInstructions = await window.aivicApi.list(4);
      if (updatedInstructions) {
        const undelivered = updatedInstructions.filter(inst => inst.ステータス === '未着手' || inst.ステータス === '承認済み');
        renderInstructions(undelivered);
      }
    }
  });

  // 一括配信
  container.querySelector('#btn-bulk-distribute').addEventListener('click', () => {
    if (selectedInstructions.size === 0) {
      alert('配信する指示書を選択してください');
      return;
    }
    container.querySelector('#btn-distribute').click();
  });

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    const instructions = await window.aivicApi.list(4);
    if (instructions) {
      const undelivered = instructions.filter(inst => inst.ステータス === '未着手' || inst.ステータス === '承認済み');
      renderInstructions(undelivered);
    }
    selectedInstructions.clear();
    container.querySelector('#select-all').checked = false;
  });

  // 作業開始ボタン
  container.querySelector('#btn-work-start').addEventListener('click', () => {
    window.showScreen("scr-1780995200157");
  });

  // 履歴モーダル制御
  container.querySelector('#close-history')?.addEventListener('click', () => {
    container.querySelector('#history-modal').style.display = 'none';
  });
}

function(container, apiUrl, tables) {
  let materials = [];

  // 1. 再描画関数の定義
  function renderWorkResults(rows) {
    const tbody = container.querySelector("#work-results-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td style="padding: 0.5rem; color: var(--text);">${r.生産指示書ID || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.工程ID || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.作業者ID || ""}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--text);">${r.実績数量 || 0}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--text);">${r.良品数量 || 0}</td>
        <td style="padding: 0.5rem; text-align: center;">
          <span style="padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; background: ${r.作業状況 === '完了' ? 'rgba(34, 197, 94, 0.2)' : r.作業状況 === '進行中' ? 'rgba(59, 130, 246, 0.2)' : 'rgba(156, 163, 175, 0.2)'}; color: var(--text);">
            ${r.作業状況 || "未開始"}
          </span>
        </td>
        <td style="padding: 0.5rem; text-align: center;">
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem; margin-right: 0.25rem;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  function renderMaterials() {
    const tbody = container.querySelector("#materials-tbody");
    tbody.innerHTML = materials.map((m, index) => `
      <tr>
        <td style="padding: 0.5rem; color: var(--text);">${m.name}</td>
        <td style="padding: 0.5rem; text-align: right; color: var(--text);">${m.consumption}</td>
        <td style="padding: 0.5rem; text-align: center;">
          <button class="action-btn secondary remove-material-btn" data-index="${index}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderWorkResults(rows);
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    window.aivicApi.list(0).then(rows => {
      if (rows) {
        const filtered = rows.filter(r => 
          JSON.stringify(r).toLowerCase().includes(keyword)
        );
        renderWorkResults(filtered);
      }
    });
  });

  // 4. 生産指示書選択時の製品名表示
  container.querySelector('select[name="productionOrderId"]').addEventListener("change", (e) => {
    const productNameMap = {
      "po-001": "エンジン部品A",
      "po-002": "フレーム組立B", 
      "po-003": "配線ハーネスC",
      "po-004": "制御基板D"
    };
    const productNameInput = container.querySelector('input[name="productName"]');
    productNameInput.value = productNameMap[e.target.value] || "";
  });

  // 5. 資材追加機能
  container.querySelector("#add-material").addEventListener("click", () => {
    const materialSelect = container.querySelector("#material-select");
    const consumptionInput = container.querySelector("#material-consumption");

    if (materialSelect.value && consumptionInput.value) {
      const materialName = materialSelect.options[materialSelect.selectedIndex].text;
      materials.push({
        name: materialName,
        consumption: parseFloat(consumptionInput.value)
      });

      renderMaterials();
      materialSelect.value = "";
      consumptionInput.value = "";
    }
  });

  // 6. 資材削除機能
  container.addEventListener("click", (e) => {
    const removeBtn = e.target.closest(".remove-material-btn");
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      materials.splice(index, 1);
      renderMaterials();
    }
  });

  // 7. 作業実績登録
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const form = container.querySelector("#work-result-form");
    const formData = new FormData(form);

    const workResult = {
      生産指示書ID: formData.get("productionOrderId"),
      工程ID: formData.get("processId"),
      作業者ID: formData.get("workerId"),
      作業開始日時: formData.get("startTime"),
      作業終了日時: formData.get("endTime"),
      実績数量: parseInt(formData.get("actualQuantity")) || 0,
      良品数量: parseInt(formData.get("goodQuantity")) || 0,
      不良品数量: parseInt(formData.get("defectQuantity")) || 0,
      作業状況: formData.get("endTime") ? "完了" : "進行中",
      備考: `使用資材: ${materials.map(m => `${m.name}:${m.consumption}`).join(", ")}`
    };

    if (!workResult.生産指示書ID || !workResult.工程ID || !workResult.作業者ID) {
      alert("必須項目を入力してください");
      return;
    }

    const saved = await window.aivicApi.save(0, workResult);
    if (saved) {
      alert("作業実績を登録しました");
      form.reset();
      materials = [];
      renderMaterials();
      window.aivicApi.list(0).then(renderWorkResults);
    }
  });

  // 8. 進捗更新ボタン
  container.querySelector("#btn-progress").addEventListener("click", () => {
    window.showScreen("scr-1780995279362");
  });

  // 9. クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#work-result-form").reset();
    materials = [];
    renderMaterials();
  });

  // 10. 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この作業実績を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      window.aivicApi.list(0).then(renderWorkResults);
    }

    if (editBtn) {
      // 編集機能（簡易実装）
      const row = editBtn.closest("tr");
      const id = editBtn.dataset.id;
      alert(`作業実績ID: ${id} の編集機能は今後実装予定です`);
    }
  });

  // 初期描画
  renderMaterials();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const PRODUCTION_ORDER_INDEX = 3; // 生産指示書
  const PRODUCTION_RESULTS_INDEX = 4; // 作業実績
  const ALERT_INDEX = 12; // アラート通知

  // DOM要素取得
  const resultsTbody = container.querySelector('#results-tbody');
  const searchOrderNo = container.querySelector('#search-order-no');
  const searchProduct = container.querySelector('#search-product');
  const searchLine = container.querySelector('#search-line');
  const searchDateFrom = container.querySelector('#search-date-from');
  const searchDateTo = container.querySelector('#search-date-to');
  const btnSearch = container.querySelector('#btn-search');
  const btnClear = container.querySelector('#btn-clear');
  const btnExport = container.querySelector('#btn-export');
  const alertList = container.querySelector('#alert-list');

  // KPI要素
  const kpiTotalQty = container.querySelector('#kpi-total-qty');
  const kpiCompletion = container.querySelector('#kpi-completion');
  const kpiQuality = container.querySelector('#kpi-quality');
  const kpiAlerts = container.querySelector('#kpi-alerts');

  // 実績一覧の再描画関数
  function renderResults(results) {
    if (!results || results.length === 0) {
      resultsTbody.innerHTML = '<tr><td colspan="11" style="text-align: center; color: var(--text-muted); padding: 2rem;">該当する実績データがありません</td></tr>';
      return;
    }

    resultsTbody.innerHTML = results.map(result => {
      const progressRate = result.計画数量 > 0 ? Math.round((result.実績数量 || 0) / result.計画数量 * 100) : 0;
      const statusColor = result.ステータス === '完了' ? '#22c55e' : 
                         result.ステータス === '進行中' ? '#3b82f6' : 
                         result.ステータス === '遅延' ? '#ef4444' : '#6b7280';

      return `
        <tr data-id="${result.生産指示書ID || result.id}" style="cursor: pointer;">
          <td>${result.生産指示書番号 || ''}</td>
          <td>${result.製品名 || ''}</td>
          <td>${result.製造ライン名 || result.ライン名 || ''}</td>
          <td style="text-align: right;">${(result.生産予定数量 || result.計画数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(result.生産実績数量 || result.実績数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(result.良品数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(result.不良品数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="height: 100%; background: ${progressRate >= 100 ? '#22c55e' : progressRate >= 80 ? '#3b82f6' : '#f59e0b'}; width: ${Math.min(progressRate, 100)}%; transition: width 0.3s;"></div>
              </div>
              <span style="font-size: 0.85em; min-width: 40px;">${progressRate}%</span>
            </div>
          </td>
          <td>
            <span style="padding: 0.2rem 0.6rem; border-radius: 12px; font-size: 0.8em; background: ${statusColor}20; color: ${statusColor}; border: 1px solid ${statusColor}40;">
              ${result.ステータス || '未着手'}
            </span>
          </td>
          <td>${result.生産完了予定日時 ? new Date(result.生産完了予定日時).toLocaleDateString('ja-JP') : ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${result.生産指示書ID || result.id}" style="padding: 0.3rem 0.8rem; font-size: 0.85em;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // アラート一覧の再描画関数
  function renderAlerts(alerts) {
    if (!alerts || alerts.length === 0) {
      alertList.innerHTML = '<div style="color: var(--text-muted); font-size: 0.9em;">現在、アラートはありません</div>';
      return;
    }

    const recentAlerts = alerts.slice(0, 3); // 最新3件のみ表示
    alertList.innerHTML = recentAlerts.map(alert => {
      const severityColor = alert.重要度 === '緊急' ? '#ef4444' : 
                           alert.重要度 === '高' ? '#f59e0b' : '#3b82f6';

      return `
        <div style="display: flex; align-items: center; gap: 0.8rem; padding: 0.6rem; background: ${severityColor}10; border-left: 3px solid ${severityColor}; border-radius: 4px;">
          <div style="width: 8px; height: 8px; border-radius: 50%; background: ${severityColor};"></div>
          <div style="flex: 1;">
            <div style="font-size: 0.9em; color: var(--text); font-weight: 500;">${alert.タイトル || alert.アラート種別 || ''}</div>
            <div style="font-size: 0.8em; color: var(--text-muted);">${alert.メッセージ内容 || ''}</div>
          </div>
          <div style="font-size: 0.8em; color: var(--text-muted);">
            ${alert.作成日時 ? new Date(alert.作成日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}
          </div>
        </div>
      `;
    }).join('');
  }

  // KPI更新関数
  function updateKPIs(results, alerts) {
    if (!results) return;

    const totalQty = results.reduce((sum, r) => sum + (r.生産実績数量 || r.実績数量 || 0), 0);
    const totalPlan = results.reduce((sum, r) => sum + (r.生産予定数量 || r.計画数量 || 0), 0);
    const totalGood = results.reduce((sum, r) => sum + (r.良品数量 || 0), 0);
    const totalBad = results.reduce((sum, r) => sum + (r.不良品数量 || 0), 0);

    const completionRate = totalPlan > 0 ? (totalQty / totalPlan * 100) : 0;
    const qualityRate = (totalGood + totalBad) > 0 ? (totalGood / (totalGood + totalBad) * 100) : 0;
    const alertCount = alerts ? alerts.filter(a => a.通知ステータス !== '完了').length : 0;

    kpiTotalQty.textContent = totalQty.toLocaleString();
    kpiCompletion.textContent = completionRate.toFixed(1) + '%';
    kpiQuality.textContent = qualityRate.toFixed(1) + '%';
    kpiAlerts.textContent = alertCount.toString();
  }

  // 検索フィルタ関数
  function filterResults(results) {
    if (!results) return [];

    return results.filter(result => {
      // 生産指示書番号フィルタ
      if (searchOrderNo.value && !result.生産指示書番号?.includes(searchOrderNo.value)) {
        return false;
      }

      // 製品名フィルタ
      if (searchProduct.value && !result.製品名?.includes(searchProduct.value)) {
        return false;
      }

      // 製造ラインフィルタ
      if (searchLine.value && result.製造ライン名 !== searchLine.value && result.ライン名 !== searchLine.value) {
        return false;
      }

      // 日付範囲フィルタ
      if (searchDateFrom.value || searchDateTo.value) {
        const resultDate = new Date(result.生産開始実績日時 || result.作業開始日時 || result.作成日時);
        if (searchDateFrom.value && resultDate < new Date(searchDateFrom.value)) {
          return false;
        }
        if (searchDateTo.value && resultDate > new Date(searchDateTo.value + 'T23:59:59')) {
          return false;
        }
      }

      return true;
    });
  }

  // 検索実行
  async function executeSearch() {
    try {
      const [results, alerts] = await Promise.all([
        window.aivicApi.list(PRODUCTION_ORDER_INDEX),
        window.aivicApi.list(ALERT_INDEX)
      ]);

      const filteredResults = filterResults(results);
      renderResults(filteredResults);
      renderAlerts(alerts);
      updateKPIs(filteredResults, alerts);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(PRODUCTION_ORDER_INDEX).then(results => {
      if (!results || results.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['生産指示書番号', '製品名', '製造ライン', '計画数量', '実績数量', '良品数量', '不良数量', '進捗率', 'ステータス', '完了予定日'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...results.map(r => [
          r.生産指示書番号 || '',
          r.製品名 || '',
          r.製造ライン名 || r.ライン名 || '',
          r.生産予定数量 || r.計画数量 || 0,
          r.生産実績数量 || r.実績数量 || 0,
          r.良品数量 || 0,
          r.不良品数量 || 0,
          r.計画数量 > 0 ? Math.round((r.実績数量 || 0) / r.計画数量 * 100) + '%' : '0%',
          r.ステータス || '',
          r.生産完了予定日時 ? new Date(r.生産完了予定日時).toLocaleDateString('ja-JP') : ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `生産実績_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    });
  }

  // イベントリスナー登録
  btnSearch.addEventListener('click', executeSearch);

  btnClear.addEventListener('click', () => {
    searchOrderNo.value = '';
    searchProduct.value = '';
    searchLine.value = '';
    searchDateFrom.value = '';
    searchDateTo.value = '';
    executeSearch();
  });

  btnExport.addEventListener('click', exportCSV);

  // 行クリックで詳細画面遷移
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1780995300997');
      return;
    }

    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      window.showScreen('scr-1780995300997');
    }
  });

  // 初期データ読み込み
  executeSearch();
}

function(container, apiUrl, tables) {
  let selectedInstructionId = null;
  let selectedInstruction = null;

  // 生産指示書一覧を描画
  function renderInstructions(instructions) {
    const listEl = container.querySelector("#instruction-list");
    if (!instructions || instructions.length === 0) {
      listEl.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 1rem;">該当する生産指示書がありません</div>';
      return;
    }

    listEl.innerHTML = instructions.map(inst => `
      <div class="instruction-item" data-id="${inst.id}" 
           style="padding: 0.75rem; border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; margin-bottom: 0.5rem; cursor: pointer; background: rgba(0,0,0,0.1);">
        <div style="font-weight: 500; color: var(--text);">${inst.生産指示書番号 || ''}</div>
        <div style="font-size: 0.85em; color: var(--text-muted);">${inst.製品名 || ''} | 予定: ${inst.生産予定数量 || 0}個</div>
        <div style="font-size: 0.8em; color: var(--text-muted);">ライン: ${inst.ライン名 || ''}</div>
      </div>
    `).join('');
  }

  // 進捗履歴を描画
  function renderProgressHistory(records) {
    const tbody = container.querySelector("#progress-history-tbody");
    if (!records || records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">履歴がありません</td></tr>';
      return;
    }

    tbody.innerHTML = records.map(record => `
      <tr data-id="${record.id}">
        <td>${record.更新日時 ? new Date(record.更新日時).toLocaleTimeString() : ''}</td>
        <td>${record.生産指示書番号 || ''}</td>
        <td>${record.工程名 || ''}</td>
        <td>${record.作業者名 || ''}</td>
        <td>${record.進捗率 || 0}%</td>
        <td>${record.完了数量 || 0}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.8em; 
                       background: ${record.品質結果 === '合格' ? '#22c55e' : record.品質結果 === '不合格' ? '#ef4444' : '#f59e0b'}; 
                       color: #fff;">
            ${record.品質結果 || '-'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${record.id}" style="font-size: 0.8em; padding: 0.3rem 0.6rem;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${record.id}" style="font-size: 0.8em; padding: 0.3rem 0.6rem;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(instructions => {
    renderInstructions(instructions || []);
  });

  window.aivicApi.list(12).then(progressRecords => {
    const today = new Date().toDateString();
    const todayRecords = (progressRecords || []).filter(record => 
      record.更新日時 && new Date(record.更新日時).toDateString() === today
    );
    renderProgressHistory(todayRecords);
  });

  // 生産指示書検索
  container.querySelector("#btn-search-instruction").addEventListener("click", async () => {
    const searchNo = container.querySelector("#search-instruction-no").value.trim();
    const instructions = await window.aivicApi.list(4);

    if (searchNo) {
      const filtered = instructions.filter(inst => 
        inst.生産指示書番号 && inst.生産指示書番号.includes(searchNo)
      );
      renderInstructions(filtered);
    } else {
      renderInstructions(instructions);
    }
  });

  // 生産指示書選択
  container.addEventListener("click", (e) => {
    const instructionItem = e.target.closest(".instruction-item");
    if (instructionItem) {
      // 既存の選択を解除
      container.querySelectorAll(".instruction-item").forEach(item => {
        item.style.background = "rgba(0,0,0,0.1)";
        item.style.borderColor = "rgba(255,255,255,0.1)";
      });

      // 新しい選択を適用
      instructionItem.style.background = "rgba(var(--primary-rgb, 59, 130, 246), 0.15)";
      instructionItem.style.borderColor = "var(--primary)";

      selectedInstructionId = instructionItem.dataset.id;

      // 選択された生産指示書の情報を表示
      window.aivicApi.list(4).then(instructions => {
        selectedInstruction = instructions.find(inst => inst.id === selectedInstructionId);
        if (selectedInstruction) {
          container.querySelector("#display-instruction-no").textContent = selectedInstruction.生産指示書番号 || '';
          container.querySelector("#display-product-name").textContent = selectedInstruction.製品名 || '';
          container.querySelector("#display-line-name").textContent = selectedInstruction.ライン名 || '';
          container.querySelector("#display-planned-qty").textContent = `${selectedInstruction.生産予定数量 || 0}個`;
          container.querySelector("#selected-instruction-info").style.display = "block";
        }
      });
    }
  });

  // 進捗更新フォーム送信
  container.querySelector("#progress-form").addEventListener("submit", async (e) => {
    e.preventDefault();

    if (!selectedInstructionId) {
      alert("生産指示書を選択してください");
      return;
    }

    const formData = new FormData(e.target);
    const qualityResult = container.querySelector('input[name="qualityResult"]:checked')?.value || '';

    const progressData = {
      生産指示書ID: selectedInstructionId,
      生産指示書番号: selectedInstruction?.生産指示書番号 || '',
      工程ID: formData.get('process'),
      工程名: container.querySelector("#process-select option:checked").textContent,
      作業者ID: formData.get('worker'),
      作業者名: container.querySelector("#worker-select option:checked").textContent,
      計画開始日時: formData.get('startTime'),
      実績開始日時: formData.get('startTime'),
      実績終了日時: formData.get('endTime') || null,
      進捗率: parseInt(formData.get('progressRate')) || 0,
      完了数量: parseInt(formData.get('actualQty')) || 0,
      不良品数量: parseInt(formData.get('defectQty')) || 0,
      工程ステータス: parseInt(formData.get('progressRate')) >= 100 ? '完了' : '進行中',
      品質結果: qualityResult === 'pass' ? '合格' : qualityResult === 'fail' ? '不合格' : qualityResult === 'recheck' ? '要再検査' : '',
      備考: formData.get('remarks') || '',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(12, progressData);
    if (saved) {
      alert("進捗を更新しました");
      e.target.reset();
      container.querySelector("#selected-instruction-info").style.display = "none";
      selectedInstructionId = null;
      selectedInstruction = null;

      // 履歴を再読み込み
      const progressRecords = await window.aivicApi.list(12);
      const today = new Date().toDateString();
      const todayRecords = progressRecords.filter(record => 
        record.更新日時 && new Date(record.更新日時).toDateString() === today
      );
      renderProgressHistory(todayRecords);
    }
  });

  // 実績記録画面への遷移
  container.querySelector("#btn-record-result").addEventListener("click", () => {
    window.showScreen("scr-1780995289968");
  });

  // 履歴の編集・削除
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この進捗記録を削除しますか？")) return;

      await window.aivicApi.delete(12, deleteBtn.dataset.id);
      const progressRecords = await window.aivicApi.list(12);
      const today = new Date().toDateString();
      const todayRecords = progressRecords.filter(record => 
        record.更新日時 && new Date(record.更新日時).toDateString() === today
      );
      renderProgressHistory(todayRecords);
    }

    if (editBtn) {
      // 編集機能は簡略化（実際の業務では詳細な編集画面が必要）
      alert("編集機能は別画面で実装されます");
    }
  });

  // 現在時刻を開始時刻にセット
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector("#start-time").value = now.toISOString().slice(0, 16);
}

function(container, apiUrl, tables) {
  let materialList = [];

  // 1. 再描画関数の定義
  function renderRecords(records) {
    const tbody = container.querySelector("#records-tbody");
    tbody.innerHTML = records.map(r => {
      const startTime = r.作業開始日時 ? new Date(r.作業開始日時) : null;
      const endTime = r.作業終了日時 ? new Date(r.作業終了日時) : null;
      const workTime = startTime && endTime ? 
        Math.round((endTime - startTime) / (1000 * 60)) + "分" : "-";

      return `
        <tr data-id="${r.作業実績ID || ''}" style="border-bottom: 1px solid rgba(255,255,255,0.08);">
          <td style="padding: 0.7rem; color: var(--text); font-size: 0.9rem;">${r.生産指示書ID || '-'}</td>
          <td style="padding: 0.7rem; color: var(--text); font-size: 0.9rem;">${r.工程ID || '-'}</td>
          <td style="padding: 0.7rem; color: var(--text); font-size: 0.9rem;">${r.作業者ID || '-'}</td>
          <td style="padding: 0.7rem; text-align: center; color: var(--text); font-size: 0.9rem;">${r.実績数量 || 0}</td>
          <td style="padding: 0.7rem; text-align: center; color: var(--text); font-size: 0.9rem;">${r.良品数量 || 0}</td>
          <td style="padding: 0.7rem; text-align: center; color: var(--text); font-size: 0.9rem;">${r.不良品数量 || 0}</td>
          <td style="padding: 0.7rem; text-align: center; color: var(--text); font-size: 0.9rem;">${workTime}</td>
          <td style="padding: 0.7rem; text-align: center;">
            <button class="action-btn secondary edit-btn" data-id="${r.作業実績ID || ''}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 0.3rem 0.6rem; border-radius: 3px; font-size: 0.8rem;">編集</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function renderMaterials() {
    const tbody = container.querySelector("#material-tbody");
    tbody.innerHTML = materialList.map((mat, index) => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 0.7rem; color: var(--text); font-size: 0.9rem;">${mat.name}</td>
        <td style="padding: 0.7rem; text-align: right; color: var(--text); font-size: 0.9rem;">${mat.quantity}</td>
        <td style="padding: 0.7rem; text-align: center;">
          <button class="remove-material-btn" data-index="${index}" style="background: transparent; color: #ff6a6a; border: 1px solid #ff6a6a; padding: 0.2rem 0.5rem; border-radius: 3px; font-size: 0.8rem;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ描画
  const workRecordsTable = tables.find(t => t.tableName === "作業実績") || tables[0];
  renderRecords(workRecordsTable.records || []);

  // 3. 生産指示書選択時の製品名自動入力
  const productOrderSelect = container.querySelector("#production-order");
  const productNameInput = container.querySelector("#product-name");

  const productMap = {
    "po-001": "エンジン部品A",
    "po-002": "フレーム組立B", 
    "po-003": "配線ハーネスC",
    "po-004": "制御基板D"
  };

  productOrderSelect.addEventListener("change", function() {
    const selectedOrder = this.value;
    productNameInput.value = productMap[selectedOrder] || "";
  });

  // 4. 資材追加ボタン
  container.querySelector("#btn-add-material").addEventListener("click", function() {
    const materialSelect = container.querySelector("#material-select");
    const quantityInput = container.querySelector("#material-quantity");

    if (!materialSelect.value || !quantityInput.value) {
      alert("資材名と使用量を入力してください");
      return;
    }

    const materialName = materialSelect.options[materialSelect.selectedIndex].text;
    materialList.push({
      id: materialSelect.value,
      name: materialName,
      quantity: quantityInput.value
    });

    renderMaterials();
    materialSelect.value = "";
    quantityInput.value = "";
  });

  // 5. 実績登録ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    const form = container.querySelector("#production-form");
    const formData = new FormData(form);

    const workerId = formData.get("worker_id");
    const startTime = formData.get("start_time");
    const actualQuantity = formData.get("actual_quantity");

    if (!workerId || !startTime || !actualQuantity) {
      alert("必須項目を入力してください");
      return;
    }

    const recordData = {
      生産指示書ID: formData.get("production_order_id"),
      工程ID: formData.get("process_id"),
      作業者ID: workerId,
      作業開始日時: startTime,
      作業終了日時: formData.get("end_time"),
      実績数量: parseInt(formData.get("actual_quantity")) || 0,
      良品数量: parseInt(formData.get("good_quantity")) || 0,
      不良品数量: parseInt(formData.get("defect_quantity")) || 0,
      作業状況: "完了",
      備考: materialList.length > 0 ? `使用資材: ${materialList.map(m => `${m.name}(${m.quantity})`).join(", ")}` : ""
    };

    const tableIndex = tables.findIndex(t => t.tableName === "作業実績");
    const saved = await window.aivicApi.save(tableIndex >= 0 ? tableIndex : 0, recordData);

    if (saved) {
      alert("製造実績を登録しました");
      form.reset();
      materialList = [];
      renderMaterials();

      // 最新データで再描画
      const records = await window.aivicApi.list(tableIndex >= 0 ? tableIndex : 0);
      if (records) renderRecords(records);
    }
  });

  // 6. クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", function() {
    container.querySelector("#production-form").reset();
    materialList = [];
    renderMaterials();
  });

  // 7. 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", async function() {
    const tableIndex = tables.findIndex(t => t.tableName === "作業実績");
    const records = await window.aivicApi.list(tableIndex >= 0 ? tableIndex : 0);
    if (records) renderRecords(records);
  });

  // 8. 履歴画面へボタン
  container.querySelector("#btn-history").addEventListener("click", function() {
    window.showScreen("scr-1780995189769"); // 作業履歴検索・照合画面
  });

  // 9. イベントデリゲーション（編集・資材削除）
  container.addEventListener("click", async function(e) {
    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      // 編集機能は作業実績登録・工程引き継ぎ画面で実装
      window.showScreen("scr-1780995149463");
      return;
    }

    // 資材削除ボタン
    const removeBtn = e.target.closest(".remove-material-btn");
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      materialList.splice(index, 1);
      renderMaterials();
      return;
    }
  });

  // 10. 初期データ読み込み
  window.aivicApi.list(tables.findIndex(t => t.tableName === "作業実績") >= 0 ? 
    tables.findIndex(t => t.tableName === "作業実績") : 0)
    .then(records => {
      if (records) renderRecords(records);
    });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const resultCount = container.querySelector("#result-count");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // 進捗管理テーブルのインデックスを取得
  const progressTableIndex = tables.findIndex(t => t.tableName === "進捗管理");
  const productTableIndex = tables.findIndex(t => t.tableName === "製品マスタ");
  const lineTableIndex = tables.findIndex(t => t.tableName === "製造ライン");
  const processTableIndex = tables.findIndex(t => t.tableName === "工程マスタ");
  const instructionTableIndex = tables.findIndex(t => t.tableName === "生産指示書");
  const qualityTableIndex = tables.findIndex(t => t.tableName === "品質検査結果");
  const alertTableIndex = tables.findIndex(t => t.tableName === "アラート通知");

  let currentData = [];

  // ステータスバッジの色を取得
  function getStatusBadge(status) {
    const colors = {
      '未着手': 'background: rgba(128,128,128,0.2); color: var(--text);',
      '進行中': 'background: rgba(59,130,246,0.2); color: #3b82f6;',
      '完了': 'background: rgba(34,197,94,0.2); color: #22c55e;',
      '中断': 'background: rgba(245,158,11,0.2); color: #f59e0b;',
      '遅延': 'background: rgba(239,68,68,0.2); color: #ef4444;'
    };
    const style = colors[status] || 'background: rgba(128,128,128,0.2); color: var(--text);';
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem; ${style}">${status}</span>`;
  }

  // アラートアイコンを表示
  function getAlertIcon(hasAlert) {
    if (hasAlert) {
      return '<span style="color: #ef4444; font-size: 1.1rem;" title="異常値検出">⚠️</span>';
    }
    return '';
  }

  // 進捗バーを表示
  function getProgressBar(rate) {
    const percentage = Math.min(100, Math.max(0, rate));
    const color = percentage >= 100 ? '#22c55e' : percentage >= 80 ? '#3b82f6' : percentage >= 50 ? '#f59e0b' : '#ef4444';
    return `
      <div style="display: flex; align-items: center; gap: 0.5rem;">
        <div style="width: 60px; height: 8px; background: rgba(128,128,128,0.2); border-radius: 4px; overflow: hidden;">
          <div style="width: ${percentage}%; height: 100%; background: ${color}; transition: width 0.3s;"></div>
        </div>
        <span style="font-size: 0.85rem; color: var(--text);">${percentage}%</span>
      </div>
    `;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    currentData = rows;
    resultCount.textContent = rows.length;

    tbody.innerHTML = rows.map(row => {
      // 関連データを取得
      const product = tables[productTableIndex]?.records?.find(p => p.製品ID === row.製品ID) || {};
      const line = tables[lineTableIndex]?.records?.find(l => l.ライン_ID === row.製造ラインID) || {};
      const process = tables[processTableIndex]?.records?.find(p => p.工程ID === row.工程ID) || {};
      const instruction = tables[instructionTableIndex]?.records?.find(i => i.生産指示書ID === row.生産指示書ID) || {};

      // アラートチェック
      const hasAlert = tables[alertTableIndex]?.records?.some(a => 
        a.生産指示書ID === row.生産指示書ID && a.通知ステータス !== '完了'
      ) || false;

      return `
        <tr data-id="${row.進捗管理ID}" style="cursor: pointer;">
          <td>${instruction.生産指示書番号 || '-'}</td>
          <td>${product.製品名 || '-'}</td>
          <td>${line.ライン名 || '-'}</td>
          <td>${process.工程名 || '-'}</td>
          <td style="text-align: right;">${(row.計画数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(row.完了数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(row.良品数量 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(row.不良品数量 || 0).toLocaleString()}</td>
          <td>${getProgressBar(row.進捗率 || 0)}</td>
          <td>${getStatusBadge(row.工程ステータス || '未着手')} ${getAlertIcon(hasAlert)}</td>
          <td>${formatDateTime(row.実績開始日時)}</td>
          <td>${formatDateTime(row.実績終了日時)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.進捗管理ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細モーダル表示
  function showDetail(progressId) {
    const row = currentData.find(r => r.進捗管理ID === progressId);
    if (!row) return;

    const product = tables[productTableIndex]?.records?.find(p => p.製品ID === row.製品ID) || {};
    const line = tables[lineTableIndex]?.records?.find(l => l.ライン_ID === row.製造ラインID) || {};
    const process = tables[processTableIndex]?.records?.find(p => p.工程ID === row.工程ID) || {};
    const instruction = tables[instructionTableIndex]?.records?.find(i => i.生産指示書ID === row.生産指示書ID) || {};

    // 品質検査結果を取得
    const qualityResults = tables[qualityTableIndex]?.records?.filter(q => 
      q.生産指示書ID === row.生産指示書ID
    ) || [];

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem;">
        <div>
          <h4 style="font-size: 1rem; font-weight: 500; margin-bottom: 0.75rem; color: var(--text);">基本情報</h4>
          <div style="space-y: 0.5rem;">
            <div><strong>生産指示書番号:</strong> ${instruction.生産指示書番号 || '-'}</div>
            <div><strong>製品名:</strong> ${product.製品名 || '-'}</div>
            <div><strong>製品コード:</strong> ${product.製品コード || '-'}</div>
            <div><strong>製造ライン:</strong> ${line.ライン名 || '-'}</div>
            <div><strong>工程名:</strong> ${process.工程名 || '-'}</div>
            <div><strong>工程区分:</strong> ${process.工程区分 || '-'}</div>
          </div>
        </div>

        <div>
          <h4 style="font-size: 1rem; font-weight: 500; margin-bottom: 0.75rem; color: var(--text);">生産実績</h4>
          <div style="space-y: 0.5rem;">
            <div><strong>計画数量:</strong> ${(row.計画数量 || 0).toLocaleString()}</div>
            <div><strong>完了数量:</strong> ${(row.完了数量 || 0).toLocaleString()}</div>
            <div><strong>良品数量:</strong> ${(row.良品数量 || 0).toLocaleString()}</div>
            <div><strong>不良品数量:</strong> ${(row.不良品数量 || 0).toLocaleString()}</div>
            <div><strong>進捗率:</strong> ${row.進捗率 || 0}%</div>
            <div><strong>ステータス:</strong> ${getStatusBadge(row.工程ステータス || '未着手')}</div>
          </div>
        </div>
      </div>

      <div style="margin-top: 1.5rem;">
        <h4 style="font-size: 1rem; font-weight: 500; margin-bottom: 0.75rem; color: var(--text);">スケジュール</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
          <div>
            <div><strong>計画開始:</strong> ${formatDateTime(row.計画開始日時)}</div>
            <div><strong>計画終了:</strong> ${formatDateTime(row.計画終了日時)}</div>
          </div>
          <div>
            <div><strong>実績開始:</strong> ${formatDateTime(row.実績開始日時)}</div>
            <div><strong>実績終了:</strong> ${formatDateTime(row.実績終了日時)}</div>
          </div>
        </div>
        ${row.遅延フラグ ? `<div style="margin-top: 0.5rem; color: #ef4444;"><strong>遅延理由:</strong> ${row.遅延理由 || '-'}</div>` : ''}
      </div>

      ${qualityResults.length > 0 ? `
        <div style="margin-top: 1.5rem;">
          <h4 style="font-size: 1rem; font-weight: 500; margin-bottom: 0.75rem; color: var(--text);">品質検査結果</h4>
          <div style="max-height: 200px; overflow-y: auto;">
            ${qualityResults.map(q => `
              <div style="padding: 0.5rem; border: 1px solid var(--border); border-radius: 4px; margin-bottom: 0.5rem;">
                <div><strong>${q.検査項目名}:</strong> ${q.実測値} (基準: ${q.検査基準値}) - ${getStatusBadge(q.判定結果)}</div>
                <div style="font-size: 0.85rem; color: var(--text-muted);">検査日時: ${formatDateTime(q.検査日時)}</div>
              </div>
            `).join('')}
          </div>
        </div>
      ` : ''}

      ${row.備考 ? `
        <div style="margin-top: 1.5rem;">
          <h4 style="font-size: 1rem; font-weight: 500; margin-bottom: 0.75rem; color: var(--text);">備考</h4>
          <div style="padding: 0.75rem; background: rgba(128,128,128,0.1); border-radius: 4px;">
            ${row.備考}
          </div>
        </div>
      ` : ''}
    `;

    detailModal.style.display = 'block';
  }

  // フィルタリング関数
  function filterData() {
    const lineFilter = container.querySelector("#line-filter").value;
    const productFilter = container.querySelector("#product-filter").value.toLowerCase();
    const statusFilter = container.querySelector("#status-filter").value;
    const dateFrom = container.querySelector("#date-from").value;
    const dateTo = container.querySelector("#date-to").value;

    return window.aivicApi.list(progressTableIndex).then(rows => {
      if (!rows) return;

      const filtered = rows.filter(row => {
        // 関連データを取得
        const product = tables[productTableIndex]?.records?.find(p => p.製品ID === row.製品ID) || {};
        const line = tables[lineTableIndex]?.records?.find(l => l.ライン_ID === row.製造ラインID) || {};

        // ライン フィルタ
        if (lineFilter && line.ライン名 !== lineFilter) return false;

        // 製品名フィルタ
        if (productFilter && !product.製品名?.toLowerCase().includes(productFilter)) return false;

        // ステータスフィルタ
        if (statusFilter && row.工程ステータス !== statusFilter) return false;

        // 日付フィルタ
        if (dateFrom || dateTo) {
          const startDate = row.実績開始日時 ? new Date(row.実績開始日時) : null;
          if (dateFrom && startDate && startDate < new Date(dateFrom)) return false;
          if (dateTo && startDate && startDate > new Date(dateTo + 'T23:59:59')) return false;
        }

        return true;
      });

      renderRows(filtered);
    });
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = [
      '生産指示書番号', '製品名', '製造ライン', '工程', '計画数量', '実績数量', 
      '良品数量', '不良品数量', '進捗率', 'ステータス', '開始日時', '完了日時'
    ];

    const csvData = currentData.map(row => {
      const product = tables[productTableIndex]?.records?.find(p => p.製品ID === row.製品ID) || {};
      const line = tables[lineTableIndex]?.records?.find(l => l.ライン_ID === row.製造ラインID) || {};
      const process = tables[processTableIndex]?.records?.find(p => p.工程ID === row.工程ID) || {};
      const instruction = tables[instructionTableIndex]?.records?.find(i => i.生産指示書ID === row.生産指示書ID) || {};

      return [
        instruction.生産指示書番号 || '',
        product.製品名 || '',
        line.ライン名 || '',
        process.工程名 || '',
        row.計画数量 || 0,
        row.完了数量 || 0,
        row.良品数量 || 0,
        row.不良品数量 || 0,
        row.進捗率 || 0,
        row.工程ステータス || '',
        formatDateTime(row.実績開始日時),
        formatDateTime(row.実績終了日時)
      ].map(field => `"${field}"`).join(',');
    });

    const csv = '\uFEFF' + [headers.join(','), ...csvData].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `生産実績_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(progressTableIndex).then(rows => {
    if (rows) renderRows(rows);
  });

  // 検索ボタン
