  container.querySelector("#btn-manufacturing-history").addEventListener("click", () => {
    window.showScreen("scr-1780995311464");
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.style.display = "none";
    }
  });
