function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];

  // 再描画関数の定義
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const statusBadge = getStatusBadge(row.作業状況 || row.工程ステータス || '完了');
      return `
        <tr data-id="${row.id || row.作業履歴ID || row.生産指示書ID}">
          <td>${row.生産指示書番号 || row.生産指示書ID || ''}</td>
          <td>${row.製品名 || ''}</td>
          <td>${row.ライン名 || row.製造ライン || ''}</td>
          <td>${row.工程名 || row.工程区分 || ''}</td>
          <td>${row.ロット番号 || ''}</td>
          <td>${formatDateTime(row.作業開始日時 || row.生産開始実績日時)}</td>
          <td>${formatDateTime(row.作業終了日時 || row.生産完了実績日時)}</td>
          <td>${row.実績数量 || row.生産実績数量 || 0}</td>
          <td>${row.良品数量 || 0}</td>
          <td>${row.不良品数量 || 0}</td>
          <td>${row.作業者名 || row.担当者名 || ''}</td>
          <td>${statusBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id || row.作業履歴ID || row.生産指示書ID}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join("");

    updatePagination(rows.length);
  }

  function getStatusBadge(status) {
    const statusColors = {
      '完了': 'background: #22c55e; color: #fff;',
      '進行中': 'background: #3b82f6; color: #fff;',
      '未着手': 'background: #6b7280; color: #fff;',
      '中断': 'background: #f59e0b; color: #fff;',
      '異常': 'background: #ef4444; color: #fff;'
    };
    const style = statusColors[status] || statusColors['完了'];
    return `<span style="padding: 0.125rem 0.5rem; border-radius: 12px; font-size: 0.75rem; ${style}">${status}</span>`;
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const prevBtn = container.querySelector("#btn-prev-page");
    const nextBtn = container.querySelector("#btn-next-page");

    pageInfo.textContent = `${currentPage} / ${totalPages} ページ (${totalItems}件)`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  // 初期データの読み込みと描画
  async function loadHistoryData() {
    try {
      // 作業履歴テーブルから履歴データを取得
      const workHistoryIndex = tables.findIndex(t => t.tableName === '作業履歴');
      const productionOrderIndex = tables.findIndex(t => t.tableName === '生産指示書');

      if (workHistoryIndex >= 0) {
        const workHistory = await window.aivicApi.list(workHistoryIndex);
        allHistoryData = workHistory || tables[workHistoryIndex].records || [];
      } else if (productionOrderIndex >= 0) {
        const productionOrders = await window.aivicApi.list(productionOrderIndex);
        allHistoryData = productionOrders || tables[productionOrderIndex].records || [];
      } else {
        // フォールバック: 最初のテーブルを使用
        allHistoryData = await window.aivicApi.list(0) || tables[0].records || [];
      }

      filteredData = [...allHistoryData];
      renderHistoryRows(filteredData);
    } catch (error) {
      console.error('履歴データの読み込みに失敗しました:', error);
      allHistoryData = tables[0]?.records || [];
      filteredData = [...allHistoryData];
      renderHistoryRows(filteredData);
    }
  }

  // 検索機能
  function performSearch() {
    const productName = container.querySelector("#product-name-search").value.toLowerCase();
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const lineFilter = container.querySelector("#line-filter").value;
    const lotNumber = container.querySelector("#lot-number-search").value.toLowerCase();
    const selectedProcesses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);

    filteredData = allHistoryData.filter(row => {
      // 製品名フィルター
      if (productName && !(row.製品名 || '').toLowerCase().includes(productName)) {
        return false;
      }

      // 日付範囲フィルター
      const workStartDate = row.作業開始日時 || row.生産開始実績日時;
      if (startDate && workStartDate && new Date(workStartDate) < new Date(startDate)) {
        return false;
      }
      if (endDate && workStartDate && new Date(workStartDate) > new Date(endDate + 'T23:59:59')) {
        return false;
      }

      // 製造ラインフィルター
      if (lineFilter && (row.ライン名 || row.製造ライン) !== lineFilter) {
        return false;
      }

      // ロット番号フィルター
      if (lotNumber && !(row.ロット番号 || '').toLowerCase().includes(lotNumber)) {
        return false;
      }

      // 工程フィルター
      if (selectedProcesses.length > 0) {
        const processName = row.工程名 || row.工程区分 || '';
        if (!selectedProcesses.some(proc => processName.includes(proc))) {
          return false;
        }
      }

      return true;
    });

    currentPage = 1;
    renderHistoryRows(filteredData);
  }

  // CSVエクスポート機能
  function exportToCSV() {
    const headers = ['生産指示書番号', '製品名', '製造ライン', '工程', 'ロット番号', '作業開始', '作業終了', '実績数量', '良品数量', '不良品数量', '作業者', 'ステータス'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filteredData.map(row => [
        row.生産指示書番号 || row.生産指示書ID || '',
        row.製品名 || '',
        row.ライン名 || row.製造ライン || '',
        row.工程名 || row.工程区分 || '',
        row.ロット番号 || '',
        formatDateTime(row.作業開始日時 || row.生産開始実績日時),
        formatDateTime(row.作業終了日時 || row.生産完了実績日時),
        row.実績数量 || row.生産実績数量 || 0,
        row.良品数量 || 0,
        row.不良品数量 || 0,
        row.作業者名 || row.担当者名 || '',
        row.作業状況 || row.工程ステータス || '完了'
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `製造履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細表示機能
  function showDetail(id) {
    const record = allHistoryData.find(r => (r.id || r.作業履歴ID || r.生産指示書ID) == id);
    if (!record) return;

    const detailContent = container.querySelector("#detail-content");
    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
        <div>
          <h4 style="margin: 0 0 0.5rem 0; color: var(--text);">基本情報</h4>
          <div style="display: flex; flex-direction: column; gap: 0.5rem;">
            <div><strong>生産指示書番号:</strong> ${record.生産指示書番号 || record.生産指示書ID || ''}</div>
            <div><strong>製品名:</strong> ${record.製品名 || ''}</div>
            <div><strong>製造ライン:</strong> ${record.ライン名 || record.製造ライン || ''}</div>
            <div><strong>工程:</strong> ${record.工程名 || record.工程区分 || ''}</div>
            <div><strong>ロット番号:</strong> ${record.ロット番号 || ''}</div>
          </div>
        </div>
        <div>
          <h4 style="margin: 0 0 0.5rem 0; color: var(--text);">実績情報</h4>
          <div style="display: flex; flex-direction: column; gap: 0.5rem;">
            <div><strong>作業開始:</strong> ${formatDateTime(record.作業開始日時 || record.生産開始実績日時)}</div>
            <div><strong>作業終了:</strong> ${formatDateTime(record.作業終了日時 || record.生産完了実績日時)}</div>
            <div><strong>実績数量:</strong> ${record.実績数量 || record.生産実績数量 || 0}</div>
            <div><strong>良品数量:</strong> ${record.良品数量 || 0}</div>
            <div><strong>不良品数量:</strong> ${record.不良品数量 || 0}</div>
            <div><strong>作業者:</strong> ${record.作業者名 || record.担当者名 || ''}</div>
          </div>
        </div>
      </div>
      ${record.備考 ? `<div style="margin-top: 1rem;"><h4 style="margin: 0 0 0.5rem 0; color: var(--text);">備考</h4><p>${record.備考}</p></div>` : ''}
      <div style="margin-top: 1.5rem; text-align: right;">
        <button onclick="window.showScreen('scr-1780995322568')" class="action-btn">作業実績詳細</button>
      </div>
    `;

    container.querySelector("#detail-modal").style.display = "block";
  }

  // イベントリスナーの登録
  container.querySelector("#btn-search").addEventListener("click", performSearch);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#line-filter").value = "";
    container.querySelector("#lot-number-search").value = "";
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    filteredData = [...allHistoryData];
    currentPage = 1;
    renderHistoryRows(filteredData);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportToCSV);

  // ページネーション
  container.querySelector("#btn-prev-page").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistoryRows(filteredData);
    }
  });

  container.querySelector("#btn-next-page").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderHistoryRows(filteredData);
    }
  });

  // モーダル制御
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = "none";
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadHistoryData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-results-tbody");
  const detailContent = container.querySelector("#detail-content");
  const qualityContent = container.querySelector("#quality-content");

  // 進捗インジケーター要素
