  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.作業実績ID || r.id}" style="cursor: pointer;">
        <td>${r.作業実績ID || r.id || ""}</td>
        <td>${r.製造ライン名 || "未設定"}</td>
        <td>${r.製品名 || "未設定"}</td>
        <td>${r.工程名 || "未設定"}</td>
        <td>${r.作業者名 || "未設定"}</td>
        <td>${r.作業開始日時 ? new Date(r.作業開始日時).toLocaleString() : ""}</td>
        <td>${r.作業終了日時 ? new Date(r.作業終了日時).toLocaleString() : ""}</td>
        <td>${r.実績数量 || 0}</td>
        <td>${r.良品数量 || 0}</td>
        <td>${r.不良品数量 || 0}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 0.75rem; 
            ${r.作業状況 === '完了' ? 'background: #28a745; color: #fff;' : 
              r.作業状況 === '進行中' ? 'background: #ffc107; color: #000;' : 
