    // 進捗インジケーター更新
    updateProgressIndicators(rows);
  }

  // 進捗インジケーター更新
  function updateProgressIndicators(rows) {
    const total = rows.length;
    const completed = rows.filter(r => r.作業状況 === '完了').length;
    const inProgress = rows.filter(r => r.作業状況 === '進行中').length;

    const totalDefects = rows.reduce((sum, r) => sum + (parseInt(r.不良品数量) || 0), 0);
    const totalProduced = rows.reduce((sum, r) => sum + (parseInt(r.実績数量) || 0), 0);
    const defectRate = totalProduced > 0 ? ((totalDefects / totalProduced) * 100).toFixed(1) : 0;

    totalCountEl.textContent = total;
    completedCountEl.textContent = completed;
    progressCountEl.textContent = inProgress;
    defectRateEl.textContent = defectRate + '%';
