        <div style="color: var(--text-muted); font-size: 0.75rem; margin-bottom: 0.25rem;">備考</div>
        <div style="background: rgba(0,0,0,0.25); padding: 0.5rem; border-radius: 4px; min-height: 60px;">
          ${workResult.備考 || "特記事項なし"}
        </div>
      </div>
    `;
