  // 品質検査結果表示（サンプル）
  function showQualityResults(workResultId) {
    qualityContent.innerHTML = `
      <div style="font-size: 0.875rem;">
        <div style="display: flex; justify-content: space-between; margin-bottom: 0.5rem;">
          <span>寸法検査</span>
          <span style="color: #28a745; font-weight: bold;">合格</span>
        </div>
        <div style="display: flex; justify-content: space-between; margin-bottom: 0.5rem;">
          <span>外観検査</span>
          <span style="color: #28a745; font-weight: bold;">合格</span>
        </div>
        <div style="display: flex; justify-content: space-between; margin-bottom: 0.5rem;">
          <span>機能検査</span>
          <span style="color: #ffc107; font-weight: bold;">要確認</span>
