    const workerId = container.querySelector("#worker-select").value;

    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (lineId && !r.製造ライン名?.includes(lineId)) return false;
      if (productName && !r.製品名?.toLowerCase().includes(productName.toLowerCase())) return false;
      if (startDate && r.作業開始日時 && new Date(r.作業開始日時) < new Date(startDate)) return false;
      if (endDate && r.作業開始日時 && new Date(r.作業開始日時) > new Date(endDate + 'T23:59:59')) return false;
      if (selectedProcesses.length > 0 && !selectedProcesses.some(p => r.工程名?.includes(p))) return false;
      if (workerId && !r.作業者名?.includes(workerId)) return false;
      return true;
    });

    renderRows(filtered);
