      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["実績ID", "製造ライン", "製品名", "工程", "作業者", "開始日時", "終了日時", "実績数量", "良品数量", "不良品数量", "状況", "備考"];
    const csvContent = [
      headers.join(","),
      ...rows.map(r => [
        r.作業実績ID || r.id || "",
        r.製造ライン名 || "",
        r.製品名 || "",
        r.工程名 || "",
        r.作業者名 || "",
        r.作業開始日時 ? new Date(r.作業開始日時).toLocaleString() : "",
        r.作業終了日時 ? new Date(r.作業終了日時).toLocaleString() : "",
        r.実績数量 || 0,
        r.良品数量 || 0,
        r.不良品数量 || 0,
        r.作業状況 || "",
        `"${(r.備考 || "").replace(/"/g, '""')}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `作業実績_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 6. 行クリック・詳細ボタン
  container.addEventListener("click", async (e) => {
    const row = e.target.closest("tr[data-id]");
    const detailBtn = e.target.closest(".detail-btn");

    if (detailBtn || (row && !e.target.closest("button"))) {
      const id = (detailBtn?.dataset.id) || row?.dataset.id;
      if (!id) return;

      const rows = await window.aivicApi.list(5);
      if (!rows) return;

      const workResult = rows.find(r => (r.作業実績ID || r.id) === id);
      if (workResult) {
        showDetail(workResult);
        showQualityResults(id);
      }
    }
  });
}

function(container, apiUrl, tables) {
  let allPlans = [];

  // 進捗率計算関数
  function calculateProgress(planned, actual) {
    if (!planned || planned === 0) return 0;
    return Math.min(Math.round((actual / planned) * 100), 100);
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const colors = {
      '未着手': '#6b7280',
      '進行中': '#3b82f6', 
      '完了': '#10b981',
      '中断': '#f59e0b',
      '遅延': '#ef4444'
    };
    const color = colors[status] || '#6b7280';
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${color}20; color: ${color}; border: 1px solid ${color}40;">${status}</span>`;
  }

  // 品質アイコン生成
  function getQualityIcon(planId) {
    // 品質検査結果テーブルから該当する結果を検索
    const qualityResults = tables.find(t => t.tableName === '品質検査結果')?.records || [];
    const result = qualityResults.find(r => r.生産指示書ID === planId);

    if (!result) return '<span style="color: var(--text-muted);">-</span>';

    const isPass = result.判定結果 === '合格';
    const color = isPass ? '#10b981' : '#ef4444';
    const icon = isPass ? '✓' : '✗';
    return `<span style="color: ${color}; font-weight: bold;">${icon}</span>`;
  }

  // KPI更新
  function updateKPIs(plans) {
    const total = plans.length;
    const inProgress = plans.filter(p => p.ステータス === '進行中').length;
    const completed = plans.filter(p => p.ステータス === '完了').length;
    const delayed = plans.filter(p => p.ステータス === '遅延').length;

    container.querySelector('#total-plans').textContent = total;
    container.querySelector('#in-progress').textContent = inProgress;
    container.querySelector('#completed').textContent = completed;
    container.querySelector('#delayed').textContent = delayed;
  }

  // テーブル再描画
  function renderPlans(plans) {
    const tbody = container.querySelector('#plan-tbody');
    allPlans = plans;
    updateKPIs(plans);

    tbody.innerHTML = plans.map(plan => {
      const progress = calculateProgress(plan.生産予定数量, plan.生産実績数量 || 0);
      const startDate = plan.生産開始予定日時 ? new Date(plan.生産開始予定日時).toLocaleDateString() : '-';
      const endDate = plan.生産完了予定日時 ? new Date(plan.生産完了予定日時).toLocaleDateString() : '-';

      // 製品名を取得
      const products = tables.find(t => t.tableName === '製品マスタ')?.records || [];
      const product = products.find(p => p.製品ID === plan.製品ID);
      const productName = product?.製品名 || '-';

      // 製造ライン名を取得
      const lines = tables.find(t => t.tableName === '製造ライン')?.records || [];
      const line = lines.find(l => l.ライン_ID === plan.製造ラインID);
      const lineName = line?.ライン名 || '-';

      return `
        <tr data-id="${plan.生産指示書ID}" style="cursor: pointer;">
          <td>${plan.生産指示書番号 || '-'}</td>
          <td>${productName}</td>
          <td>${lineName}</td>
          <td style="text-align: right;">${plan.生産予定数量?.toLocaleString() || 0}</td>
          <td style="text-align: right;">${(plan.生産実績数量 || 0).toLocaleString()}</td>
          <td style="text-align: center;">
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="height: 100%; background: var(--primary); width: ${progress}%; transition: width 0.3s;"></div>
              </div>
              <span style="font-size: 0.8rem; color: var(--text-muted);">${progress}%</span>
            </div>
          </td>
          <td>${getStatusBadge(plan.ステータス || '未着手')}</td>
          <td style="font-size: 0.85rem;">${startDate}</td>
          <td style="font-size: 0.85rem;">${endDate}</td>
          <td style="text-align: center;">${getQualityIcon(plan.生産指示書ID)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${plan.生産指示書ID}" style="padding: 0.25rem 0.5rem; font-size: 0.8rem;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示
  function showDetail(planId) {
    const plan = allPlans.find(p => p.生産指示書ID === planId);
    if (!plan) return;

    const products = tables.find(t => t.tableName === '製品マスタ')?.records || [];
    const lines = tables.find(t => t.tableName === '製造ライン')?.records || [];
    const product = products.find(p => p.製品ID === plan.製品ID);
    const line = lines.find(l => l.ライン_ID === plan.製造ラインID);

    const content = container.querySelector('#detail-content');
    content.innerHTML = `
      <div>
        <label style="font-size: 0.8rem; color: var(--text-muted);">生産指示書番号</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${plan.生産指示書番号 || '-'}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">製品名</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${product?.製品名 || '-'}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">製造ライン</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${line?.ライン名 || '-'}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">優先度</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${plan.優先度 || '-'}</div>
      </div>
      <div>
        <label style="font-size: 0.8rem; color: var(--text-muted);">生産予定数量</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${(plan.生産予定数量 || 0).toLocaleString()}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">生産実績数量</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${(plan.生産実績数量 || 0).toLocaleString()}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">良品数量</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${(plan.良品数量 || 0).toLocaleString()}</div>

        <label style="font-size: 0.8rem; color: var(--text-muted);">不良品数量</label>
        <div style="margin-bottom: 1rem; color: var(--text);">${(plan.不良品数量 || 0).toLocaleString()}</div>
      </div>
    `;

    if (plan.備考) {
      content.innerHTML += `
        <div style="grid-column: 1 / -1;">
          <label style="font-size: 0.8rem; color: var(--text-muted);">備考</label>
          <div style="color: var(--text); padding: 0.5rem; background: var(--bg-main); border-radius: 4px; margin-top: 0.25rem;">${plan.備考}</div>
        </div>
      `;
    }

    container.querySelector('#detail-modal').style.display = 'block';
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['生産指示書番号', '製品名', '製造ライン', '生産予定数量', '生産実績数量', '進捗率', 'ステータス', '開始予定日', '完了予定日'];
    const products = tables.find(t => t.tableName === '製品マスタ')?.records || [];
    const lines = tables.find(t => t.tableName === '製造ライン')?.records || [];

    const csvData = allPlans.map(plan => {
      const product = products.find(p => p.製品ID === plan.製品ID);
      const line = lines.find(l => l.ライン_ID === plan.製造ラインID);
      const progress = calculateProgress(plan.生産予定数量, plan.生産実績数量 || 0);
      const startDate = plan.生産開始予定日時 ? new Date(plan.生産開始予定日時).toLocaleDateString() : '';
      const endDate = plan.生産完了予定日時 ? new Date(plan.生産完了予定日時).toLocaleDateString() : '';

      return [
        plan.生産指示書番号 || '',
        product?.製品名 || '',
        line?.ライン名 || '',
        plan.生産予定数量 || 0,
        plan.生産実績数量 || 0,
        progress + '%',
        plan.ステータス || '',
        startDate,
        endDate
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `生産計画一覧_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 検索処理
  function performSearch() {
    const productName = container.querySelector('#product-name-search').value.toLowerCase();
    const lineFilter = container.querySelector('#line-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const statusFilter = container.querySelector('#status-filter').value;

    window.aivicApi.list(4).then(plans => {
      if (!plans) return;

      const products = tables.find(t => t.tableName === '製品マスタ')?.records || [];
      const lines = tables.find(t => t.tableName === '製造ライン')?.records || [];

      let filtered = plans.filter(plan => {
        // 製品名フィルタ
        if (productName) {
          const product = products.find(p => p.製品ID === plan.製品ID);
          if (!product?.製品名?.toLowerCase().includes(productName)) return false;
        }

        // ラインフィルタ
        if (lineFilter) {
          const line = lines.find(l => l.ライン_ID === plan.製造ラインID);
          if (line?.ライン名 !== lineFilter) return false;
        }

        // 日付フィルタ
        if (startDate && plan.生産開始予定日時) {
          const planDate = new Date(plan.生産開始予定日時).toISOString().slice(0, 10);
          if (planDate < startDate) return false;
        }
        if (endDate && plan.生産完了予定日時) {
          const planDate = new Date(plan.生産完了予定日時).toISOString().slice(0, 10);
          if (planDate > endDate) return false;
        }

        // ステータスフィルタ
        if (statusFilter && plan.ステータス !== statusFilter) return false;

        return true;
      });

      renderPlans(filtered);
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(plans => {
    if (plans) renderPlans(plans);
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#product-name-search').value = '';
    container.querySelector('#line-filter').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#status-filter').value = '';
    window.aivicApi.list(4).then(plans => {
      if (plans) renderPlans(plans);
    });
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 画面遷移
  container.querySelector('#btn-demand-forecast').addEventListener('click', () => {
    window.showScreen("scr-1780995149463");
  });

  container.querySelector('#btn-production-order').addEventListener('click', () => {
    window.showScreen("scr-1780995137049");
  });

  // 詳細モーダル制御
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      e.stopPropagation();
      showDetail(detailBtn.dataset.id);
      return;
    }

    const row = e.target.closest('tr[data-id]');
    if (row) {
      showDetail(row.dataset.id);
    }
  });

  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#btn-close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  // モーダル外クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').style.display = 'none';
    }
  });

  // 作業履歴・品質結果ボタン（プレースホルダー）
  container.querySelector('#btn-work-history').addEventListener('click', () => {
    alert('作業履歴画面への遷移機能は今後実装予定です');
  });

  container.querySelector('#btn-quality-result').addEventListener('click', () => {
    alert('品質結果画面への遷移機能は今後実装予定です');
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderHistoricalData(rows) {
    const tbody = container.querySelector("#historical-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.製品名 || ""}</td>
        <td>${r.年月 || ""}</td>
        <td style="text-align: right;">${r.実績数量 || 0}</td>
        <td style="text-align: right;">${r.予測数量 || 0}</td>
        <td style="text-align: right; color: ${Math.abs(r.誤差率 || 0) > 10 ? '#ef4444' : '#10b981'};">${r.誤差率 || 0}%</td>
      </tr>
    `).join("");
  }

  // チャート描画関数
  function drawForecastChart() {
    const canvas = container.querySelector("#forecast-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景グリッド
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const x = (width / 10) * i;
      const y = (height / 10) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // 実績データライン（青）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    const actualData = [120, 135, 142, 138, 155, 148, 162, 158, 170, 165];
    for (let i = 0; i < actualData.length; i++) {
      const x = (width / (actualData.length - 1)) * i;
      const y = height - (actualData[i] / 200) * height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測データライン（オレンジ）
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    const forecastData = [165, 172, 178, 185, 190, 195];
    for (let i = 0; i < forecastData.length; i++) {
      const x = width * 0.6 + (width * 0.4 / (forecastData.length - 1)) * i;
      const y = height - (forecastData[i] / 200) * height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#d1d5db';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績', 10, 20);
    ctx.fillText('予測', 10, 35);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(50, 12, 20, 3);
    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(50, 27, 20, 3);
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector("#seasonal-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 2 - 20;

    ctx.clearRect(0, 0, width, height);

    // 季節性円グラフ
    const seasonalData = [
      { label: '春', value: 0.25, color: '#10b981' },
      { label: '夏', value: 0.35, color: '#f59e0b' },
      { label: '秋', value: 0.22, color: '#ef4444' },
      { label: '冬', value: 0.18, color: '#3b82f6' }
    ];

    let currentAngle = -Math.PI / 2;
    seasonalData.forEach(item => {
      const sliceAngle = item.value * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = item.color;
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);
      ctx.fillStyle = '#ffffff';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, labelX, labelY);
      ctx.fillText(`${(item.value * 100).toFixed(0)}%`, labelX, labelY + 15);

      currentAngle += sliceAngle;
    });
  }

  function drawTrendChart() {
    const canvas = container.querySelector("#trend-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // トレンドライン
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, height * 0.8);
    ctx.lineTo(width, height * 0.2);
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    const points = [
      {x: width * 0.1, y: height * 0.75},
      {x: width * 0.3, y: height * 0.65},
      {x: width * 0.5, y: height * 0.45},
      {x: width * 0.7, y: height * 0.35},
      {x: width * 0.9, y: height * 0.25}
    ];

    points.forEach(point => {
      ctx.beginPath();
      ctx.arc(point.x, point.y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });
  }

  // 2. 初期データ描画
  const historicalData = [
    { id: '1', 製品名: 'プロダクトA', 年月: '2024-01', 実績数量: 120, 予測数量: 115, 誤差率: 4.3 },
    { id: '2', 製品名: 'プロダクトA', 年月: '2024-02', 実績数量: 135, 予測数量: 128, 誤差率: 5.5 },
    { id: '3', 製品名: 'プロダクトB', 年月: '2024-01', 実績数量: 85, 予測数量: 92, 誤差率: -7.6 },
    { id: '4', 製品名: 'プロダクトB', 年月: '2024-02', 実績数量: 98, 予測数量: 95, 誤差率: 3.2 },
    { id: '5', 製品名: 'プロダクトC', 年月: '2024-01', 実績数量: 156, 予測数量: 148, 誤差率: 5.4 }
  ];

  renderHistoricalData(historicalData);
  drawForecastChart();
  drawSeasonalChart();
  drawTrendChart();

  // 3. イベントリスナー登録
  container.querySelector("#btn-analyze").addEventListener("click", () => {
    const period = container.querySelector("#forecast-period").value;
    const category = container.querySelector("#product-category").value;
    const model = container.querySelector("#forecast-model").value;

    if (!period || !model) {
      alert("予測期間と予測モデルを選択してください");
      return;
    }

    // 予測分析実行（模擬）
    setTimeout(() => {
      container.querySelector("#accuracy-rate").textContent = (85 + Math.random() * 10).toFixed(1) + "%";
      container.querySelector("#mae-value").textContent = (10 + Math.random() * 10).toFixed(1);
      container.querySelector("#rmse-value").textContent = (15 + Math.random() * 10).toFixed(1);
      container.querySelector("#mape-value").textContent = (5 + Math.random() * 10).toFixed(1) + "%";

      drawForecastChart();
      drawSeasonalChart();
      drawTrendChart();
    }, 1000);
  });

  container.querySelector("#btn-production-order").addEventListener("click", () => {
    window.showScreen("scr-1780995230897");
  });

  container.querySelector("#btn-export").addEventListener("click", () => {
    const csvData = [
      ['製品名', '予測期間', '予測数量', '信頼区間下限', '信頼区間上限'],
      ['プロダクトA', '2024-03', '172', '165', '179'],
      ['プロダクトA', '2024-04', '178', '170', '186'],
      ['プロダクトB', '2024-03', '102', '95', '109'],
      ['プロダクトB', '2024-04', '108', '100', '116']
    ];

    const csvContent = '\uFEFF' + csvData.map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'demand_forecast_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
  });

  container.querySelector("#btn-refresh").addEventListener("click", async () => {
    if (window.aivicApi) {
      const rows = await window.aivicApi.list(0);
      if (rows) {
        renderHistoricalData(rows);
      }
    }
    drawForecastChart();
    drawSeasonalChart();
    drawTrendChart();
  });

  container.querySelector("#btn-alert-setting").addEventListener("click", () => {
    alert("アラート設定機能は開発中です");
  });
}
